EOF
    else
        LABEL=$([ "$ID" = rocky ] && echo Rocky || echo AlmaLinux)
        cat > "$REPO_DIR/vps-tools-base.repo" <<EOF
[vps-tools-baseos]
name=${LABEL} - BaseOS
baseurl=${BASE}/\$releasever/BaseOS/\$basearch/os/
enabled=1
gpgcheck=1
gpgkey=${GPGKEY}
[vps-tools-appstream]
name=${LABEL} - AppStream
baseurl=${BASE}/\$releasever/AppStream/\$basearch/os/
enabled=1
gpgcheck=1
gpgkey=${GPGKEY}
[vps-tools-crb]
name=${LABEL} - CRB
baseurl=${BASE}/\$releasever/CRB/\$basearch/os/
enabled=1
gpgcheck=1
gpgkey=${GPGKEY}
[vps-tools-extras]
name=${LABEL} - Extras
baseurl=${BASE}/\$releasever/extras/\$basearch/os/
enabled=1
gpgcheck=1
gpgkey=${GPGKEY}
EOF
    fi
    if dnf makecache -q; then
        info "${LABEL} 源已更新 ✓"
    else
        rm -rf "$REPO_DIR"
        mkdir -p "$REPO_DIR"
        cp -a "$BACKUP/." "$REPO_DIR/"
        error "新 RPM 软件源不可用，已恢复原配置"
        return 1
    fi
}

mirror_menu() {
    while true; do
        local OS_INFO; OS_INFO=$(detect_os)
        local OS_ID; OS_ID=$(echo "$OS_INFO" | cut -d: -f1)
        local OS_VER; OS_VER=$(echo "$OS_INFO" | cut -d: -f2)

        print_header "系统换源"
        echo -e "  检测到系统：${BOLD}${OS_ID} ${OS_VER}${NC}"
        echo ""
        menu_div

        case "$OS_ID" in
            ubuntu)
                menu_item "1" "阿里云  ${DIM}mirrors.aliyun.com${NC}"
                menu_item "2" "腾讯云  ${DIM}mirrors.tencent.com${NC}"
                menu_item "3" "清华  ${DIM}mirrors.tuna.tsinghua.edu.cn${NC}"
                menu_item "4" "中科大  ${DIM}mirrors.ustc.edu.cn${NC}"
                menu_item "5" "Ubuntu 官方源  ${DIM}海外${NC}"
                menu_div
                menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
                menu_div
                echo ""
                read -rp "$(ui_prompt '选择软件源 [0-5]: ')" CH
                case "$CH" in
                    1) mirror_apply_ubuntu "https://mirrors.aliyun.com/ubuntu" ;;
                    2) mirror_apply_ubuntu "https://mirrors.tencent.com/ubuntu" ;;
                    3) mirror_apply_ubuntu "https://mirrors.tuna.tsinghua.edu.cn/ubuntu" ;;
                    4) mirror_apply_ubuntu "https://mirrors.ustc.edu.cn/ubuntu" ;;
                    5) mirror_apply_ubuntu "http://archive.ubuntu.com/ubuntu" ;;
                    0) return ;;
                    00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                    *) warn "无效选项"; sleep 1; continue ;;
                esac
                ;;
            debian)
                menu_item "1" "阿里云  ${DIM}mirrors.aliyun.com${NC}"
                menu_item "2" "腾讯云  ${DIM}mirrors.tencent.com${NC}"
                menu_item "3" "清华  ${DIM}mirrors.tuna.tsinghua.edu.cn${NC}"
                menu_item "4" "中科大  ${DIM}mirrors.ustc.edu.cn${NC}"
                menu_item "5" "Debian 官方源  ${DIM}海外${NC}"
                menu_div
                menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
                menu_div
                echo ""
                read -rp "$(ui_prompt '选择软件源 [0-5]: ')" CH
                case "$CH" in
                    1) mirror_apply_debian "https://mirrors.aliyun.com/debian" ;;
                    2) mirror_apply_debian "https://mirrors.tencent.com/debian" ;;
                    3) mirror_apply_debian "https://mirrors.tuna.tsinghua.edu.cn/debian" ;;
                    4) mirror_apply_debian "https://mirrors.ustc.edu.cn/debian" ;;
                    5) mirror_apply_debian "http://deb.debian.org/debian" ;;
                    0) return ;;
                    00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                    *) warn "无效选项"; sleep 1; continue ;;
                esac
                ;;
            centos|rocky|rhel|almalinux)
                menu_item "1" "阿里云"
                menu_item "2" "清华"
                menu_item "3" "系统默认源"
                menu_div
                menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
                menu_div
                echo ""
                read -rp "$(ui_prompt '选择软件源 [0-3]: ')" CH
                case "$CH" in
                    1) mirror_apply_centos "cn" ;;
                    2) mirror_apply_centos "edu" ;;
                    3) mirror_apply_centos "intl" ;;
                    0) return ;;
                    00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                    *) warn "无效选项"; sleep 1; continue ;;
                esac
                ;;
            *)
                warn "暂不支持自动换源的系统：${OS_ID}"
                warn "请手动修改 /etc/apt/sources.list 或对应源文件"
                echo ""
                ui_pause
                return
                ;;
        esac

        [ "${CH:-x}" != "0" ] && ui_pause
    done
}
# ══════════════════════════════════════════════════════════
#  IPv4/IPv6 配置模块
# ══════════════════════════════════════════════════════════

ip_show_status() {
    print_header "IPv4 / IPv6 状态"

    # ── IPv4 状态 ──────────────────────────────────────────
    echo -e "  ${BOLD}IPv4：${NC}"
    local V4_ADDRS
    V4_ADDRS=$(ip -4 addr show scope global 2>/dev/null | grep "inet " | awk '{print $2}')
    if [ -n "$V4_ADDRS" ]; then
        while IFS= read -r addr; do
            echo -e "    ${GREEN}▸${NC} $addr"
        done <<< "$V4_ADDRS"
    else
        echo -e "    ${YELLOW}未检测到 IPv4 地址${NC}"
    fi

    # ── IPv6 状态 ──────────────────────────────────────────
    echo ""
    echo -e "  ${BOLD}IPv6：${NC}"
    local V6_DISABLED
    V6_DISABLED=$(sysctl -n net.ipv6.conf.all.disable_ipv6 2>/dev/null)
    if [ "$V6_DISABLED" = "1" ]; then
        echo -e "    ${RED}▸ IPv6 已禁用${NC}"
    else
        local V6_ADDRS
        V6_ADDRS=$(ip -6 addr show scope global 2>/dev/null | grep "inet6" | awk '{print $2}')
        if [ -n "$V6_ADDRS" ]; then
            while IFS= read -r addr; do
                echo -e "    ${GREEN}▸${NC} $addr"
            done <<< "$V6_ADDRS"
        else
            echo -e "    ${YELLOW}▸ IPv6 已启用但无全局地址${NC}"
        fi
    fi

    # ── 优先级状态 ─────────────────────────────────────────
    echo ""
    echo -e "  ${BOLD}优先级策略：${NC}"
    local GAICONF="/etc/gai.conf"
    if grep -q "^precedence ::ffff:0:0/96  100" "$GAICONF" 2>/dev/null; then
        echo -e "    ${CYAN}▸ 当前优先：IPv4${NC}"
    else
        echo -e "    ${CYAN}▸ 当前优先：IPv6（系统默认）${NC}"
    fi

    # ── 默认路由 ───────────────────────────────────────────
    echo ""
    echo -e "  ${BOLD}默认路由：${NC}"
    ip -4 route show default 2>/dev/null | while IFS= read -r r; do
        echo -e "    ${GREEN}v4${NC} $r"
    done
    ip -6 route show default 2>/dev/null | while IFS= read -r r; do
        echo -e "    ${CYAN}v6${NC} $r"
    done
}

ip_prefer_v4() {
    print_header "设置 IPv4 优先"
    local GAICONF="/etc/gai.conf"
    confirm_change_preview "IPv4 优先" "写入 gai.conf 地址优先级规则" "不关闭 IPv6" || { warn "已取消"; return; }
    safety_arm prefer_v4 || return 1

    # 备份
    cp "$GAICONF" "${GAICONF}.bak.$(date +%Y%m%d_%H%M%S)" 2>/dev/null

    # 注释掉已有的 precedence ::ffff 行，再追加正确的
    sed -i '/^precedence ::ffff:0:0\/96/d' "$GAICONF" 2>/dev/null
    # 确保文件存在
    [ -f "$GAICONF" ] || touch "$GAICONF"
    echo "precedence ::ffff:0:0/96  100" >> "$GAICONF"

    info "已写入 IPv4 优先规则到 $GAICONF ✓"

    # 同时通过 sysctl 设置（影响内核层面）
    sysctl -w net.ipv4.conf.all.promote_secondaries=1 &>/dev/null

    echo ""
    warn "IPv4 优先已生效，部分程序需重启才能感知变化"
    echo ""
    echo -e "  验证（应显示 IPv4 连接）："
    echo -e "  ${DIM}curl -s --max-time 5 ip.sb${NC}"
    local RESULT; RESULT=$(curl -s --max-time 5 ip.sb 2>/dev/null)
    [ -n "$RESULT" ] && echo -e "  当前出口 IP：${BOLD}${RESULT}${NC}" || warn "无法连接 ip.sb 进行验证"
    audit_action "设置IPv4优先" SUCCESS
    safety_confirm
}

ip_prefer_v6() {
    print_header "设置 IPv6 优先"
    local GAICONF="/etc/gai.conf"
    confirm_change_preview "IPv6 优先" "移除脚本写入的 IPv4 优先规则" "恢复系统默认地址选择策略" || { warn "已取消"; return; }
    safety_arm prefer_v6 || return 1

    [ -f "$GAICONF" ] && cp "$GAICONF" "${GAICONF}.bak.$(date +%Y%m%d_%H%M%S)" 2>/dev/null
    [ -f "$GAICONF" ] || touch "$GAICONF"

    # 移除本脚本写入的 IPv4 优先规则，恢复 glibc 默认地址选择策略（IPv6 优先）。
    sed -i '/^precedence ::ffff:0:0\/96[[:space:]]\+100/d' "$GAICONF" 2>/dev/null

    info "已移除 IPv4 优先规则，恢复 IPv6 优先（系统默认）✓"
    echo ""
    warn "IPv6 优先已生效，部分程序需重启才能感知变化"
    echo ""
    echo -e "  验证（如网络可用，应显示 IPv6 连接）："
    echo -e "  ${DIM}curl -6 -s --max-time 5 ip.sb${NC}"
    local RESULT; RESULT=$(curl -6 -s --max-time 5 ip.sb 2>/dev/null)
    [ -n "$RESULT" ] && echo -e "  当前 IPv6 出口：${BOLD}${RESULT}${NC}" || warn "无法通过 IPv6 连接 ip.sb 进行验证"
    audit_action "设置IPv6优先" SUCCESS
    safety_confirm
}

ip_disable_v6() {
    print_header "关闭 IPv6"
    warn "关闭 IPv6 后，仅 IPv6 的服务将无法访问！"
    echo ""
    read -rp "  确认关闭？(Y/n，默认Y): " CONFIRM
    [ -z "${CONFIRM}" ] && CONFIRM="y"
    if ! echo "${CONFIRM}" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi
    confirm_change_preview "关闭 IPv6" "立即禁用所有接口 IPv6" "写入 sysctl 持久化配置" || { warn "已取消"; return; }
    safety_arm disable_v6 || return 1

    ip_apply_v6_state 1 || { error "IPv6 禁用失败，自动回滚计时器仍在运行"; return 1; }
    info "IPv6 已通过 sysctl 禁用 ✓"

    echo ""
    echo -e "  当前 IPv6 状态：${RED}${BOLD}已禁用${NC}"
    warn "如 SSH 监听了 IPv6，建议确认 SSH 配置正常后再断开连接"
    audit_action "关闭IPv6" SUCCESS
    safety_confirm
}

ip_enable_v6() {
    print_header "开启 IPv6"
    confirm_change_preview "开启 IPv6" "移除 IPv6 禁用状态" "地址获取取决于服务商和 SLAAC" || { warn "已取消"; return; }
    safety_arm enable_v6 || return 1

    ip_apply_v6_state 0 || { error "IPv6 开启失败，自动回滚计时器仍在运行"; return 1; }

    info "IPv6 已开启 ✓"
    echo ""

    # 检查是否拿到地址
    sleep 1
    local V6_ADDRS; V6_ADDRS=$(ip -6 addr show scope global 2>/dev/null | grep "inet6" | awk '{print $2}')
    if [ -n "$V6_ADDRS" ]; then
        echo -e "  检测到 IPv6 地址："
        while IFS= read -r addr; do
            echo -e "    ${GREEN}▸${NC} $addr"
        done <<< "$V6_ADDRS"
    else
        warn "已开启但暂未获取到 IPv6 地址，可能需要重启网络服务或等待 SLAAC"
        echo -e "  ${DIM}可尝试：systemctl restart networking 或 reboot${NC}"
    fi
    audit_action "开启IPv6" SUCCESS
    safety_confirm
}

ip_apply_v6_state() {
    local VALUE="$1" SYSCTL_FILE="/etc/sysctl.d/99-ipv6-disable.conf" TMP KEY
    ensure_sysctl || return 1
    mkdir -p /etc/sysctl.d || return 1
    TMP=$(mktemp "${SYSCTL_FILE}.tmp.XXXXXX") || return 1
    for KEY in net.ipv6.conf.all.disable_ipv6 net.ipv6.conf.default.disable_ipv6 net.ipv6.conf.lo.disable_ipv6; do
        printf '%s = %s\n' "$KEY" "$VALUE" >> "$TMP" || { rm -f "$TMP"; return 1; }
    done
    chmod 644 "$TMP" 2>/dev/null || true
    mv "$TMP" "$SYSCTL_FILE" || { rm -f "$TMP"; return 1; }
    sysctl -p "$SYSCTL_FILE" &>/dev/null || return 1
    for KEY in net.ipv6.conf.all.disable_ipv6 net.ipv6.conf.default.disable_ipv6 net.ipv6.conf.lo.disable_ipv6; do
        [ "$(sysctl -n "$KEY" 2>/dev/null)" = "$VALUE" ] || return 1
    done
}

ip_source_probe() {
    case "$1" in
        4) echo "1.1.1.1" ;;
        6) echo "2606:4700:4700::1111" ;;
        *) return 1 ;;
    esac
}

ip_source_default_iface() {
    local family="$1" probe route
    probe=$(ip_source_probe "$family") || return 1
    route=$(ip "-$family" route get "$probe" 2>/dev/null | head -1) || return 1
    awk '{for (i=1; i<=NF; i++) if ($i == "dev") {print $(i+1); exit}}' <<< "$route"
}

ip_source_current() {
    local family="$1" probe route
    probe=$(ip_source_probe "$family") || return 1
    route=$(ip "-$family" route get "$probe" 2>/dev/null | head -1) || return 1
    awk '{for (i=1; i<=NF; i++) if ($i == "src") {print $(i+1); exit}}' <<< "$route"
}

ip_source_addresses() {
    local family="$1" iface="$2" kind
    [ "$family" = "4" ] && kind="inet" || kind="inet6"
    ip "-$family" -o addr show dev "$iface" scope global 2>/dev/null | awk -v kind="$kind" '
        $3 == kind && $0 !~ /(^|[[:space:]])(tentative|dadfailed|deprecated|temporary)([[:space:]]|$)/ {
            sub(/\/.*/, "", $4)
            if (!seen[$4]++) print $4
        }
    '
}

ip_source_default_route() {
    local family="$1"
    ip "-$family" route show default 2>/dev/null
}

ip_source_route_replace() {
    local family="$1" route_line="$2" selected="$3" token skip_next=0
    local tokens=() output=()
    read -r -a tokens <<< "$route_line"
    [ "${#tokens[@]}" -gt 0 ] && [ "${tokens[0]}" = "default" ] || return 1
    for token in "${tokens[@]}"; do
        if [ "$skip_next" -eq 1 ]; then
            skip_next=0
            continue
        fi
        case "$token" in
            src|expires)
                skip_next=1
                ;;
            *) output+=("$token") ;;
        esac
    done
    ip "-$family" route replace "${output[@]}" src "$selected"
}

ip_source_route_restore() {
    local family="$1" route_line="$2" token skip_next=0
    local tokens=() output=()
    read -r -a tokens <<< "$route_line"
    [ "${#tokens[@]}" -gt 0 ] && [ "${tokens[0]}" = "default" ] || return 1
    for token in "${tokens[@]}"; do
        if [ "$skip_next" -eq 1 ]; then
            skip_next=0
            continue
        fi
        case "$token" in
            expires) skip_next=1 ;;
            *) output+=("$token") ;;
        esac
    done
    ip "-$family" route replace "${output[@]}"
}

ip_source_safety_arm() {
    local family="$1" route_line="$2" script token skip_next=0
    local tokens=() output=()
    cancel_safety_timer
    read -r -a tokens <<< "$route_line"
    [ "${#tokens[@]}" -gt 0 ] || return 1
    for token in "${tokens[@]}"; do
        if [ "$skip_next" -eq 1 ]; then
            skip_next=0
            continue
        fi
        case "$token" in
            expires) skip_next=1 ;;
            *) output+=("$token") ;;
        esac
    done
    mkdir -p "$VPS_DATA_DIR" || return 1
    script="$VPS_DATA_DIR/rollback_ip_source_$$_$(date +%s)_${RANDOM}.sh"
    {
        echo '#!/bin/bash'
        echo 'sleep 180'
        printf 'ip -%q route replace' "$family"
        for token in "${output[@]}"; do printf ' %q' "$token"; done
        echo ' >/dev/null 2>&1'
        printf 'logger -t vps-tools %q\n' "未确认连接，已自动恢复 IPv${family} 首选源地址"
        printf 'rm -f %q\n' "$script"
    } > "$script" || { rm -f "$script"; return 1; }
    chmod 700 "$script" || { rm -f "$script"; return 1; }
    nohup bash "$script" >/dev/null 2>&1 &
    SAFETY_PID=$!
    SAFETY_SCRIPT="$script"
    audit_action "启动防断联保护 IPv${family} 源地址切换" SUCCESS
    warn "防断联保护已启动：180 秒内未确认将自动恢复原默认路由。"
}

ip_source_verify() {
    local family="$1" selected="$2" probe actual endpoint public_ip
    probe=$(ip_source_probe "$family") || return 1
    actual=$(ip_source_current "$family" 2>/dev/null || true)
    [ "$actual" = "$selected" ] || return 1
    if [ "$family" = "4" ]; then
        endpoint="https://api.ipify.org"
    else
        endpoint="https://api64.ipify.org"
    fi
    public_ip=$(curl "-$family" --interface "$selected" -fsS --max-time 8 "$endpoint" 2>/dev/null) || return 1
    public_ip=${public_ip//$'\r'/}
    public_ip=${public_ip//$'\n'/}
    [ -n "$public_ip" ] || return 1
    IP_SOURCE_PUBLIC_IP="$public_ip"
}

ip_source_switch_family() {
    local family="$1" label iface current routes route_count route_line selected choice public_ip
    local addresses=() addr index=0
    [ "$family" = "4" ] && label="IPv4" || label="IPv6"
    iface=$(ip_source_default_iface "$family" 2>/dev/null || true)
    [ -n "$iface" ] || { error "未检测到 ${label} 默认出口网卡"; return 1; }
    routes=$(ip_source_default_route "$family" "$iface")
    route_count=$(awk 'NF {count++} END {print count+0}' <<< "$routes")
    if [ "$route_count" -ne 1 ] || grep -qw nexthop <<< "$routes"; then
        error "检测到多个或 ECMP ${label} 默认路由，已拒绝修改"
        echo -e "  ${DIM}此功能仅适用于单默认路由、同网卡多地址环境${NC}"
        return 1
    fi
    route_line=$(head -1 <<< "$routes")
    while IFS= read -r addr; do [ -n "$addr" ] && addresses+=("$addr"); done < <(ip_source_addresses "$family" "$iface")
    if [ "${#addresses[@]}" -lt 2 ]; then
        error "${iface} 上只有 ${#addresses[@]} 个可切换的稳定 ${label} 地址"
        return 1
    fi
    current=$(ip_source_current "$family" 2>/dev/null || true)

    print_header "${label} 多 IP 出口切换"
    echo -e "  网卡：${BOLD}${iface}${NC}"
    echo -e "  当前出口源地址：${BOLD}${current:-未知}${NC}"
    echo -e "  ${DIM}仅修改运行时默认路由，网络服务或 VPS 重启后可能恢复系统配置。${NC}"
    echo ""
    menu_div
    for addr in "${addresses[@]}"; do
        index=$((index + 1))
        if [ "$addr" = "$current" ]; then
            printf '  %2d) %-42s %b\n' "$index" "$addr" "${GREEN}当前${NC}"
        else
            printf '  %2d) %s\n' "$index" "$addr"
        fi
    done
    menu_item "0" "返回上级" "$RED"
    menu_div
    echo ""
    read -rp "$(ui_prompt "选择地址 [0-${#addresses[@]}]: ")" choice
    [ "$choice" = "0" ] && return 0
    [[ "$choice" =~ ^[0-9]+$ ]] && [ "$choice" -ge 1 ] && [ "$choice" -le "${#addresses[@]}" ] \
        || { warn "无效选项"; return 1; }
    selected=${addresses[$((choice - 1))]}
    [ "$selected" != "$current" ] || { info "该地址已经是当前出口源地址"; return 0; }

    confirm_change_preview "切换 ${label} 出口源地址" \
        "网卡：${iface}" "当前：${current:-自动选择}" "切换为：${selected}" \
        "仅修改运行时默认路由，不写入网络配置文件" || { warn "已取消"; return 0; }
    ip_source_safety_arm "$family" "$route_line" || { error "无法启动路由自动回滚保护"; return 1; }
    if ! ip_source_route_replace "$family" "$route_line" "$selected"; then
        cancel_safety_timer
        error "默认路由源地址切换失败"
        return 1
    fi
    if ! ip_source_verify "$family" "$selected"; then
        ip_source_route_restore "$family" "$route_line" >/dev/null 2>&1 || true
        cancel_safety_timer
        error "新源地址无法完成路由或 HTTPS 出口验证，已恢复原默认路由"
        return 1
    fi
    public_ip="$IP_SOURCE_PUBLIC_IP"
    info "${label} 首选源地址已切换为 ${selected} ✓"
    echo -e "  公网出口：${BOLD}${public_ip}${NC}"
    audit_action "切换${label}出口源地址 ${iface} ${selected}" SUCCESS
    safety_confirm
}

ip_source_switch_menu() {
    while true; do
        print_header "多 IP 出口切换"
        echo -e "  IPv4 当前源地址：${BOLD}$(ip_source_current 4 2>/dev/null || echo 未检测到)${NC}"
        echo -e "  IPv6 当前源地址：${BOLD}$(ip_source_current 6 2>/dev/null || echo 未检测到)${NC}"
        echo ""
        menu_div
        menu_pair "1" "切换 IPv4 出口地址" "2" "切换 IPv6 出口地址"
        menu_pair "0" "返回上级" "00" "退出脚本" "$RED" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-2]: ')" CH
        case "$CH" in
            1) ip_source_switch_family 4; ui_pause ;;
            2) ip_source_switch_family 6; ui_pause ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1 ;;
        esac
    done
}

ip_config_menu() {
    while true; do
        print_header "IPv4 / IPv6 配置"

        # 状态摘要
        local V6_DISABLED; V6_DISABLED=$(sysctl -n net.ipv6.conf.all.disable_ipv6 2>/dev/null)
        local V6_STATUS; [ "$V6_DISABLED" = "1" ] && V6_STATUS="${RED}${BOLD}已禁用${NC}" || V6_STATUS="${GREEN}${BOLD}已启用${NC}"
        local V4_PREF="系统默认（IPv6优先）"
        grep -q "^precedence ::ffff:0:0/96  100" /etc/gai.conf 2>/dev/null && V4_PREF="${CYAN}${BOLD}IPv4 优先${NC}"

        echo -e "  IPv6 状态：$V6_STATUS"
        echo -e "  优先级：$V4_PREF"
        echo ""
        menu_div
        menu_item "1" "查看 IPv4 / IPv6 状态"
        menu_pair "2" "设置 IPv4 优先" "3" "设置 IPv6 优先"
        menu_pair "4" "关闭 IPv6" "5" "开启 IPv6"
        menu_item "6" "多 IP 出口切换（运行时）"
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-6]: ')" CH

        case "$CH" in
            1) ip_show_status ;;
            2) ip_prefer_v4 ;;
            3) ip_prefer_v6 ;;
            4) ip_disable_v6 ;;
            5) ip_enable_v6 ;;
            6) ip_source_switch_menu; continue ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac

        [ "${CH}" != "0" ] && ui_pause
    done
}
# ══════════════════════════════════════════════════════════
#  网卡管理（Netplan / NetworkManager / ifupdown / ifcfg）
# ══════════════════════════════════════════════════════════

network_iface_name_valid() {
    local iface="${1:-}"
    [ -n "$iface" ] && [ "${#iface}" -le 15 ] \
        && [[ "$iface" =~ ^[A-Za-z0-9_-]+$ ]] \
        && [ "$iface" != lo ]
}

network_iface_valid() {
    network_iface_name_valid "$1" && [ -d "/sys/class/net/$1" ]
}

network_ipv4_valid() {
    local ip="${1:-}" part
    local parts=()
    IFS=. read -r -a parts <<< "$ip"
    [ "${#parts[@]}" -eq 4 ] || return 1
    for part in "${parts[@]}"; do
        [[ "$part" =~ ^[0-9]+$ ]] && [ "${#part}" -le 3 ] \
            && [ "$((10#$part))" -le 255 ] || return 1
        [ "${#part}" -eq 1 ] || [ "${part#0}" = "$part" ] || return 1
    done
}

network_mask_to_prefix() {
    local mask="${1:-}" octet value prefix=0 partial=no
    local parts=()
    IFS=. read -r -a parts <<< "$mask"
    [ "${#parts[@]}" -eq 4 ] || return 1
    for octet in "${parts[@]}"; do
        [[ "$octet" =~ ^[0-9]+$ ]] && [ "${#octet}" -le 3 ] || return 1
        value=$((10#$octet))
        if [ "$partial" = yes ] && [ "$value" -ne 0 ]; then
            return 1
        fi
        case "$value" in
            255) prefix=$((prefix + 8)) ;;
            254) prefix=$((prefix + 7)); partial=yes ;;
            252) prefix=$((prefix + 6)); partial=yes ;;
            248) prefix=$((prefix + 5)); partial=yes ;;
            240) prefix=$((prefix + 4)); partial=yes ;;
            224) prefix=$((prefix + 3)); partial=yes ;;
            192) prefix=$((prefix + 2)); partial=yes ;;
            128) prefix=$((prefix + 1)); partial=yes ;;
            0) partial=yes ;;
            *) return 1 ;;
        esac
    done
    [ "$prefix" -ge 1 ] && printf '%s\n' "$prefix"
}

network_prefix_to_mask() {
    local prefix="${1:-}" bits value output="" index
    [[ "$prefix" =~ ^[0-9]+$ ]] && [ "$prefix" -ge 1 ] \
        && [ "$prefix" -le 32 ] || return 1
    prefix=$((10#$prefix))
    for index in 1 2 3 4; do
        if [ "$prefix" -ge 8 ]; then
            value=255
            prefix=$((prefix - 8))
        elif [ "$prefix" -gt 0 ]; then
            bits=$prefix
            value=$((256 - (1 << (8 - bits))))
            prefix=0
        else
            value=0
        fi
        output+="${output:+.}${value}"
    done
    printf '%s\n' "$output"
}

network_ipv4_to_int() {
    local ip="$1" a b c d
    network_ipv4_valid "$ip" || return 1
    IFS=. read -r a b c d <<< "$ip"
    printf '%s\n' "$(((10#$a << 24) | (10#$b << 16) | (10#$c << 8) | 10#$d))"
}

network_gateway_is_onlink() {
    local ip="$1" gateway="$2" prefix="$3" ip_num gateway_num mask
    ip_num=$(network_ipv4_to_int "$ip") || return 1
    gateway_num=$(network_ipv4_to_int "$gateway") || return 1
    if [ "$prefix" -eq 32 ]; then
        return 1
    fi
    mask=$(((0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF))
    [ $((ip_num & mask)) -eq $((gateway_num & mask)) ]
}

network_interfaces() {
    local path iface
    for path in /sys/class/net/*; do
        [ -d "$path" ] || continue
        iface=${path##*/}
        [ "$iface" = lo ] || printf '%s\n' "$iface"
    done
}

network_nm_connection_uuid() {
    local iface="$1" uuid candidate
    command -v nmcli >/dev/null 2>&1 || return 1
    uuid=$(nmcli -g GENERAL.CON-UUID device show "$iface" 2>/dev/null | head -1)
    case "$uuid" in ""|--|*[!A-Fa-f0-9-]*) uuid="" ;; esac
    if [ -z "$uuid" ]; then
        while IFS= read -r candidate; do
            [ -n "$candidate" ] || continue
            [ "$(nmcli -g connection.interface-name connection show uuid "$candidate" 2>/dev/null)" = "$iface" ] \
                && { uuid="$candidate"; break; }
        done < <(nmcli -g UUID connection show 2>/dev/null)
    fi
    [ -n "$uuid" ] && printf '%s\n' "$uuid"
}

network_backend_detect() {
    local iface="$1" netplan_iface="" has_netplan=no
    if command -v netplan >/dev/null 2>&1; then
        find /etc/netplan -maxdepth 1 -type f \
            \( -name '*.yaml' -o -name '*.yml' \) -print -quit 2>/dev/null \
            | grep -q . && has_netplan=yes
        netplan_iface=$(netplan get "ethernets.${iface}" 2>/dev/null || true)
    fi
    if command -v netplan >/dev/null 2>&1 \
        && [ "$has_netplan" = yes ] && [ -n "$netplan_iface" ]; then
        echo netplan
    elif command -v nmcli >/dev/null 2>&1 \
        && [ "$(LC_ALL=C nmcli -g GENERAL.NM-MANAGED device show "$iface" 2>/dev/null)" = yes ]; then
        echo networkmanager
    elif command -v networkctl >/dev/null 2>&1 \
        && svc_is_active systemd-networkd \
        && LC_ALL=C networkctl status --no-pager "$iface" 2>/dev/null \
            | grep -Eq 'Network File:[[:space:]]+/'; then
        echo networkd
    elif { [ -f /etc/network/interfaces ] || command -v ifquery >/dev/null 2>&1; } \
        && { grep -RqsE "^[[:space:]]*iface[[:space:]]+${iface}[[:space:]]+inet[[:space:]]" \
                /etc/network/interfaces /etc/network/interfaces.d 2>/dev/null \
            || [ -e "/sys/class/net/$iface/device" ]; }; then
        echo ifupdown
    elif [ -f "/etc/sysconfig/network-scripts/ifcfg-${iface}" ] \
        || { [ -d /etc/sysconfig/network-scripts ] \
            && [ -e "/sys/class/net/$iface/device" ]; }; then
        echo ifcfg
    elif [ "$has_netplan" = yes ] && [ -e "/sys/class/net/$iface/device" ]; then
        echo netplan
    else
        return 1
    fi
}

network_backend_label() {
    case "$1" in
        netplan) echo "Netplan" ;;
        networkmanager) echo "NetworkManager" ;;
        networkd) echo "systemd-networkd" ;;
        ifupdown) echo "ifupdown" ;;
        ifcfg) echo "RHEL/CentOS ifcfg" ;;
        *) echo "未知" ;;
    esac
}

network_current_ipv4_cidr() {
    ip -4 -o addr show dev "$1" scope global 2>/dev/null \
        | awk '{print $4; exit}'
}

network_current_gateway() {
    ip -4 route show default dev "$1" 2>/dev/null \
        | awk '{for (i=1; i<=NF; i++) if ($i == "via") {print $(i+1); exit}}'
}

network_current_dns() {
    local iface="$1" value
    if command -v nmcli >/dev/null 2>&1; then
        while IFS= read -r value; do
            [ -n "$value" ] && [ "$value" != -- ] && printf '%s\n' "$value"
        done < <(nmcli -g IP4.DNS device show "$iface" 2>/dev/null)
    fi
    if ! command -v nmcli >/dev/null 2>&1 \
        || ! nmcli -g IP4.DNS device show "$iface" 2>/dev/null | grep -q '[0-9]'; then
        awk '$1 == "nameserver" && $2 ~ /^[0-9]+\./ {print $2}' \
            /etc/resolv.conf 2>/dev/null
    fi
}

network_show_interfaces() {
    local iface backend state mac cidr gateway dns
    print_header "网卡状态"
    while IFS= read -r iface; do
        backend=$(network_backend_detect "$iface" 2>/dev/null || echo 未识别)
        state=$(cat "/sys/class/net/$iface/operstate" 2>/dev/null || echo unknown)
        mac=$(cat "/sys/class/net/$iface/address" 2>/dev/null || true)
        cidr=$(network_current_ipv4_cidr "$iface")
        gateway=$(network_current_gateway "$iface")
        dns=$(network_current_dns "$iface" | paste -sd ',' -)
        echo -e "  ${BOLD}${iface}${NC}  ${DIM}$(network_backend_label "$backend") · $state${NC}"
        echo -e "    IPv4：${cidr:-未配置}"
        echo -e "    网关：${gateway:-未配置}"
        echo -e "    DNS ：${dns:-未检测到}"
        [ -z "$mac" ] || echo -e "    MAC ：$mac"
        echo ""
    done < <(network_interfaces)
}

network_select_interface() {
    local interfaces=() iface index=0 choice
    while IFS= read -r iface; do interfaces+=("$iface"); done < <(network_interfaces)
    [ "${#interfaces[@]}" -gt 0 ] || { error "未检测到可配置的网卡"; return 1; }
    echo ""
    menu_div
    for iface in "${interfaces[@]}"; do
        index=$((index + 1))
        printf '  %2d) %-16s  %-18s  %s\n' "$index" "$iface" \
            "$(network_current_ipv4_cidr "$iface")" \
            "$(network_backend_label "$(network_backend_detect "$iface" 2>/dev/null || true)")"
    done
    menu_item "0" "返回上级" "$RED"
    menu_div
    read -rp "$(ui_prompt "选择网卡 [0-${#interfaces[@]}]: ")" choice
    [ "$choice" = 0 ] && return 2
    [[ "$choice" =~ ^[0-9]+$ ]] && [ "$choice" -ge 1 ] \
        && [ "$choice" -le "${#interfaces[@]}" ] \
        || { warn "无效网卡编号"; return 1; }
    NETWORK_SELECTED_IFACE=${interfaces[$((choice - 1))]}
}

network_write_atomic() {
    local target="$1" mode="${2:-600}" tmp
    mkdir -p "$(dirname "$target")" || return 1
    tmp=$(mktemp "${target}.tmp.XXXXXX") || return 1
    if ! cat > "$tmp" || ! chmod "$mode" "$tmp" || ! mv -f -- "$tmp" "$target"; then
        rm -f -- "$tmp"
        return 1
    fi
}

network_netplan_write_static() {
    local iface="$1" ip_addr="$2" prefix="$3" gateway="$4" dns1="$5" dns2="$6"
    local origin="99-vps-tools-${iface}" dns_list onlink=false
    [ -z "$dns2" ] && dns_list="\"$dns1\"" || dns_list="\"$dns1\", \"$dns2\""
    network_gateway_is_onlink "$ip_addr" "$gateway" "$prefix" || onlink=true
    # netplan set writes an origin-aware override. This matters because plain
    # later YAML files concatenate address/route sequences instead of replacing
    # the earlier cloud-init or installer values.
    netplan set --origin-hint="$origin" \
        "ethernets.${iface}={dhcp4: false, addresses: [\"${ip_addr}/${prefix}\"], gateway4: null, routes: [{to: default, via: \"${gateway}\", on-link: ${onlink}}], nameservers: {addresses: [${dns_list}]}}" \
        >/dev/null 2>&1
}

network_netplan_write_dhcp() {
    local iface="$1" origin="99-vps-tools-${iface}"
    netplan set --origin-hint="$origin" \
        "ethernets.${iface}={dhcp4: true, addresses: null, gateway4: null, routes: null, nameservers: null, dhcp4-overrides: {use-dns: true, use-routes: true}}" \
        >/dev/null 2>&1
}

network_networkd_write_static() {
    local iface="$1" ip_addr="$2" prefix="$3" gateway="$4" dns1="$5" dns2="$6"
    local target="/etc/systemd/network/00-vps-tools-${iface}.network" onlink=no
    network_gateway_is_onlink "$ip_addr" "$gateway" "$prefix" || onlink=yes
    {
        printf '%s\n' '# Managed by VPS Tools. Use the network interface menu to edit.'
        printf '%s\n' '[Match]' "Name=$iface" '' '[Network]' \
            "Address=${ip_addr}/${prefix}" 'DHCP=ipv6' 'IPv6AcceptRA=yes' "DNS=$dns1"
        [ -z "$dns2" ] || printf '%s\n' "DNS=$dns2"
        printf '%s\n' '' '[Route]' 'Destination=0.0.0.0/0' "Gateway=$gateway"
        [ "$onlink" = no ] || printf '%s\n' 'GatewayOnLink=yes'
    } | network_write_atomic "$target" 600
}

network_networkd_write_dhcp() {
    local iface="$1" target="/etc/systemd/network/00-vps-tools-${iface}.network"
    {
        printf '%s\n' '# Managed by VPS Tools. Use the network interface menu to edit.'
        printf '%s\n' '[Match]' "Name=$iface" '' '[Network]' 'DHCP=yes' 'IPv6AcceptRA=yes'
    } | network_write_atomic "$target" 600
}

network_ifupdown_strip_ipv4() {
    local iface="$1" file tmp
    while IFS= read -r -d '' file; do
        [ "$file" = "/etc/network/interfaces.d/90-vps-tools-${iface}.cfg" ] && continue
        grep -Eq "^[[:space:]]*iface[[:space:]]+${iface}[[:space:]]+inet[[:space:]]" "$file" 2>/dev/null \
            || continue
        tmp=$(mktemp "${file}.tmp.XXXXXX") || return 1
        awk -v iface="$iface" '
            function emit_activation(    i, out) {
                out=$1
                for (i=2; i<=NF; i++) if ($i != iface) out=out " " $i
                if (out != $1) print out
            }
            skipping && /^[ \t]/ {next}
            skipping {skipping=0}
            ($1 == "auto" || $1 == "allow-hotplug") {
                for (i=2; i<=NF; i++) if ($i == iface) {emit_activation(); next}
            }
            $1 == "iface" && $2 == iface && $3 == "inet" {skipping=1; next}
            {print}
        ' "$file" > "$tmp" && chmod --reference="$file" "$tmp" 2>/dev/null \
            && mv -f -- "$tmp" "$file" || { rm -f -- "$tmp"; return 1; }
    done < <(find /etc/network/interfaces /etc/network/interfaces.d \
        -maxdepth 1 -type f -print0 2>/dev/null)
}

network_ifupdown_ensure_source() {
    local file=/etc/network/interfaces tmp
    mkdir -p /etc/network/interfaces.d || return 1
    [ -f "$file" ] || printf '%s\n' 'auto lo' 'iface lo inet loopback' > "$file"
    grep -Eq '^[[:space:]]*source(-directory)?[[:space:]]+/etc/network/interfaces\.d/' "$file" \
        && return 0
    tmp=$(mktemp "${file}.tmp.XXXXXX") || return 1
    { cat "$file"; printf '\nsource /etc/network/interfaces.d/*\n'; } > "$tmp" \
        && chmod --reference="$file" "$tmp" 2>/dev/null \
        && mv -f -- "$tmp" "$file" || { rm -f -- "$tmp"; return 1; }
}

network_ifupdown_write_static() {
    local iface="$1" ip_addr="$2" prefix="$3" gateway="$4" dns1="$5" dns2="$6"
    local mask target="/etc/network/interfaces.d/90-vps-tools-${iface}.cfg"
    mask=$(network_prefix_to_mask "$prefix") || return 1
    network_ifupdown_strip_ipv4 "$iface" && network_ifupdown_ensure_source || return 1
    {
        printf '%s\n' '# Managed by VPS Tools. Use the network interface menu to edit.'
        printf 'auto %s\niface %s inet static\n' "$iface" "$iface"
        printf '    address %s\n    netmask %s\n' "$ip_addr" "$mask"
        if network_gateway_is_onlink "$ip_addr" "$gateway" "$prefix"; then
            printf '    up ip route replace default via %s dev %s\n' "$gateway" "$iface"
        else
            printf '    up ip route replace default via %s dev %s onlink\n' "$gateway" "$iface"
        fi
        printf '    down ip route del default via %s dev %s 2>/dev/null || true\n' "$gateway" "$iface"
        printf '    dns-nameservers %s%s\n' "$dns1" "${dns2:+ $dns2}"
    } | network_write_atomic "$target" 600
}

network_ifupdown_write_dhcp() {
    local iface="$1" target="/etc/network/interfaces.d/90-vps-tools-${iface}.cfg"
    network_ifupdown_strip_ipv4 "$iface" && network_ifupdown_ensure_source || return 1
    {
        printf '%s\n' '# Managed by VPS Tools. Use the network interface menu to edit.'
        printf 'auto %s\niface %s inet dhcp\n' "$iface" "$iface"
    } | network_write_atomic "$target" 600
}

network_ifcfg_write() {
    local iface="$1" mode="$2" ip_addr="${3:-}" prefix="${4:-}" gateway="${5:-}"
    local dns1="${6:-}" dns2="${7:-}" target="/etc/sysconfig/network-scripts/ifcfg-${iface}" tmp
    mkdir -p /etc/sysconfig/network-scripts || return 1
    tmp=$(mktemp "${target}.tmp.XXXXXX") || return 1
    if [ -f "$target" ]; then
        grep -Ev '^(TYPE|DEVICE|NAME|ONBOOT|BOOTPROTO|IPADDR|PREFIX|NETMASK|GATEWAY|GATEWAYDEV|DNS1|DNS2|PEERDNS|DEFROUTE)=' \
            "$target" > "$tmp" || true
    fi
    {
        cat "$tmp"
        printf '%s\n' 'TYPE=Ethernet' "DEVICE=$iface" "NAME=$iface" 'ONBOOT=yes' 'DEFROUTE=yes'
        if [ "$mode" = static ]; then
            printf '%s\n' 'BOOTPROTO=none' "IPADDR=$ip_addr" "PREFIX=$prefix" 'PEERDNS=no' "DNS1=$dns1"
            network_gateway_is_onlink "$ip_addr" "$gateway" "$prefix" \
                && printf '%s\n' "GATEWAY=$gateway"
            [ -z "$dns2" ] || printf '%s\n' "DNS2=$dns2"
        else
            printf '%s\n' 'BOOTPROTO=dhcp' 'PEERDNS=yes'
        fi
    } | network_write_atomic "$target" 600 || { rm -f -- "$tmp"; return 1; }
    rm -f -- "$tmp"
    if [ "$mode" = static ] && ! network_gateway_is_onlink "$ip_addr" "$gateway" "$prefix"; then
        network_ifcfg_route_managed "$iface" "default via $gateway dev $iface onlink"
    else
        network_ifcfg_route_managed "$iface" ""
    fi
}

network_ifcfg_route_managed() {
    local iface="$1" route_line="$2" target="/etc/sysconfig/network-scripts/route-${iface}" tmp
    tmp=$(mktemp "${target}.tmp.XXXXXX") || return 1
    if [ -f "$target" ]; then
        awk '
            $0 == "# BEGIN VPS-TOOLS MANAGED DEFAULT ROUTE" {skip=1; next}
            $0 == "# END VPS-TOOLS MANAGED DEFAULT ROUTE" {skip=0; next}
            !skip {print}
        ' "$target" > "$tmp" || { rm -f -- "$tmp"; return 1; }
    fi
    if [ -n "$route_line" ]; then
        printf '%s\n%s\n%s\n' '# BEGIN VPS-TOOLS MANAGED DEFAULT ROUTE' \
            "$route_line" '# END VPS-TOOLS MANAGED DEFAULT ROUTE' >> "$tmp" || {
                rm -f -- "$tmp"
                return 1
            }
    fi
    if [ -s "$tmp" ]; then
        chmod 600 "$tmp" && mv -f -- "$tmp" "$target"
    else
        rm -f -- "$tmp" "$target"
    fi
}

network_nm_prepare_connection() {
    local iface="$1" uuid
    uuid=$(network_nm_connection_uuid "$iface" 2>/dev/null || true)
    if [ -z "$uuid" ]; then
        nmcli connection add type ethernet ifname "$iface" \
            con-name "vps-tools-$iface" >/dev/null 2>&1 || return 1
        uuid=$(network_nm_connection_uuid "$iface" 2>/dev/null || true)
        [ -n "$uuid" ] || uuid=$(nmcli -g UUID connection show "vps-tools-$iface" 2>/dev/null | head -1)
    fi
    [ -n "$uuid" ] || return 1
    NETWORK_ACTIVE_NM_UUID="$uuid"
}

network_nm_write_static() {
    local iface="$1" ip_addr="$2" prefix="$3" gateway="$4" dns1="$5" dns2="$6"
    local dns="$dns1${dns2:+,$dns2}" route=""
    network_nm_prepare_connection "$iface" || return 1
    if network_gateway_is_onlink "$ip_addr" "$gateway" "$prefix"; then
        nmcli connection modify uuid "$NETWORK_ACTIVE_NM_UUID" \
            connection.interface-name "$iface" connection.autoconnect yes \
            ipv4.method manual ipv4.addresses "${ip_addr}/${prefix}" \
            ipv4.gateway "$gateway" ipv4.routes '' ipv4.dns "$dns" \
            ipv4.ignore-auto-dns yes ipv4.never-default no >/dev/null 2>&1
    else
        route="${gateway}/32,0.0.0.0/0 ${gateway} onlink=true"
        nmcli connection modify uuid "$NETWORK_ACTIVE_NM_UUID" \
            connection.interface-name "$iface" connection.autoconnect yes \
            ipv4.method manual ipv4.addresses "${ip_addr}/${prefix}" \
            ipv4.gateway '' ipv4.routes "$route" ipv4.dns "$dns" \
            ipv4.ignore-auto-dns yes ipv4.never-default no >/dev/null 2>&1
    fi
}

network_nm_write_dhcp() {
    local iface="$1"
    network_nm_prepare_connection "$iface" || return 1
    nmcli connection modify uuid "$NETWORK_ACTIVE_NM_UUID" \
        connection.interface-name "$iface" connection.autoconnect yes \
        ipv4.method auto ipv4.addresses '' ipv4.gateway '' ipv4.routes '' ipv4.dns '' \
        ipv4.ignore-auto-dns no ipv4.never-default no >/dev/null 2>&1
}

network_backend_validate() {
    case "$1" in
        netplan) netplan generate >/dev/null 2>&1 ;;
        networkmanager) nmcli connection show uuid "$NETWORK_ACTIVE_NM_UUID" >/dev/null 2>&1 ;;
        networkd) grep -q '^\[Network\]$' "/etc/systemd/network/00-vps-tools-$2.network" ;;
        ifupdown)
            if command -v ifquery >/dev/null 2>&1; then
                ifquery "$2" >/dev/null 2>&1
            else
                return 0
            fi
            ;;
        ifcfg) grep -q '^DEVICE=' "/etc/sysconfig/network-scripts/ifcfg-$2" ;;
        *) return 1 ;;
    esac
}

network_backend_apply() {
    local backend="$1" iface="$2"
    case "$backend" in
        netplan) netplan apply >/dev/null 2>&1 ;;
        networkmanager)
            nmcli connection reload >/dev/null 2>&1 \
                && nmcli connection up uuid "$NETWORK_ACTIVE_NM_UUID" \
                    ifname "$iface" >/dev/null 2>&1
            ;;
        networkd)
            networkctl reload >/dev/null 2>&1 \
                && { networkctl reconfigure "$iface" >/dev/null 2>&1 \
                    || svc_restart systemd-networkd; }
            ;;
        ifupdown)
            ifdown --force "$iface" >/dev/null 2>&1 || true
            ifup "$iface" >/dev/null 2>&1
            ;;
        ifcfg)
            if command -v nmcli >/dev/null 2>&1; then
                nmcli connection reload >/dev/null 2>&1 \
                    && { nmcli connection up "$iface" ifname "$iface" >/dev/null 2>&1 \
                        || nmcli device connect "$iface" >/dev/null 2>&1; }
            elif command -v ifup >/dev/null 2>&1; then
                ifdown "$iface" >/dev/null 2>&1 || true
                ifup "$iface" >/dev/null 2>&1
            else
                svc_restart network
            fi
            ;;
        *) return 1 ;;
    esac
}

network_static_configure() {
    local iface backend current_cidr current_ip current_prefix current_mask
    local current_gateway dns_values=() default_dns1 default_dns2
    local ip_addr mask prefix gateway dns1 dns2
    print_header "新增 / 修改静态 IPv4"
    network_select_interface
    case "$?" in 0) ;; 2) return 0 ;; *) return 1 ;; esac
    iface="$NETWORK_SELECTED_IFACE"
    network_iface_valid "$iface" || { error "网卡名称无效"; return 1; }
    backend=$(network_backend_detect "$iface" 2>/dev/null || true)
    [ -n "$backend" ] || { error "无法识别 $iface 的网络配置后端"; return 1; }
    current_cidr=$(network_current_ipv4_cidr "$iface")
    current_ip=${current_cidr%/*}; [ "$current_ip" = "$current_cidr" ] && current_ip=""
    current_prefix=${current_cidr#*/}; [ "$current_prefix" = "$current_cidr" ] && current_prefix=""
    [ -z "$current_prefix" ] || current_mask=$(network_prefix_to_mask "$current_prefix")
    current_gateway=$(network_current_gateway "$iface")
    while IFS= read -r dns1; do [ -n "$dns1" ] && dns_values+=("$dns1"); done \
        < <(network_current_dns "$iface")
    default_dns1=${dns_values[0]:-1.1.1.1}
    default_dns2=${dns_values[1]:-8.8.8.8}

    echo -e "  配置后端：${BOLD}$(network_backend_label "$backend")${NC}"
    read -rp "$(ui_prompt "IPv4 地址${current_ip:+ [${current_ip}]}: ")" ip_addr
    ip_addr=${ip_addr:-$current_ip}
    network_ipv4_valid "$ip_addr" || { error "IPv4 地址格式无效"; return 1; }
    read -rp "$(ui_prompt "子网掩码或前缀${current_mask:+ [${current_mask}]}: ")" mask
    mask=${mask:-$current_mask}
    if [[ "$mask" =~ ^/?[0-9]+$ ]]; then
        prefix=${mask#/}
        [ "$prefix" -ge 1 ] 2>/dev/null && [ "$prefix" -le 32 ] 2>/dev/null \
            || { error "CIDR 前缀必须是 1-32"; return 1; }
        prefix=$((10#$prefix))
        mask=$(network_prefix_to_mask "$prefix")
    else
        prefix=$(network_mask_to_prefix "$mask") \
            || { error "子网掩码无效或不连续"; return 1; }
    fi
    read -rp "$(ui_prompt "默认网关${current_gateway:+ [${current_gateway}]}: ")" gateway
    gateway=${gateway:-$current_gateway}
    network_ipv4_valid "$gateway" || { error "默认网关格式无效"; return 1; }
    [ "$gateway" != "$ip_addr" ] || { error "默认网关不能与网卡 IP 相同"; return 1; }
    read -rp "$(ui_prompt "主 DNS [${default_dns1}]: ")" dns1
    dns1=${dns1:-$default_dns1}
    network_ipv4_valid "$dns1" || { error "主 DNS 格式无效"; return 1; }
    read -rp "$(ui_prompt "备用 DNS [${default_dns2}]（输入 - 表示不设置）: ")" dns2
    dns2=${dns2:-$default_dns2}; [ "$dns2" = - ] && dns2=""
    [ -z "$dns2" ] || network_ipv4_valid "$dns2" \
        || { error "备用 DNS 格式无效"; return 1; }

    confirm_change_preview "配置 $iface 静态 IPv4" \
        "后端：$(network_backend_label "$backend")" "地址：${ip_addr}/${prefix}（${mask}）" \
        "网关：$gateway" "DNS：$dns1${dns2:+、$dns2}" \
        "应用后必须从新终端确认连接，否则 180 秒后自动恢复" || { warn "已取消"; return 0; }

    NETWORK_ROLLBACK_BACKEND="$backend"
    NETWORK_ROLLBACK_IFACE="$iface"
    NETWORK_ROLLBACK_NM_UUID=""
    [ "$backend" != networkmanager ] \
        || NETWORK_ROLLBACK_NM_UUID=$(network_nm_connection_uuid "$iface" 2>/dev/null || true)
    safety_arm network_interface || return 1
    case "$backend" in
        netplan) network_netplan_write_static "$iface" "$ip_addr" "$prefix" "$gateway" "$dns1" "$dns2" ;;
        networkmanager) network_nm_write_static "$iface" "$ip_addr" "$prefix" "$gateway" "$dns1" "$dns2" ;;
        networkd) network_networkd_write_static "$iface" "$ip_addr" "$prefix" "$gateway" "$dns1" "$dns2" ;;
        ifupdown) network_ifupdown_write_static "$iface" "$ip_addr" "$prefix" "$gateway" "$dns1" "$dns2" ;;
        ifcfg) network_ifcfg_write "$iface" static "$ip_addr" "$prefix" "$gateway" "$dns1" "$dns2" ;;
    esac || { error "写入网卡配置失败；自动回滚仍在计时"; return 1; }
    network_backend_validate "$backend" "$iface" \
        || { error "网卡配置校验失败；自动回滚仍在计时"; return 1; }
    network_backend_apply "$backend" "$iface" \
        || { error "应用网卡配置失败；请保持旧会话，自动回滚仍在计时"; return 1; }
    sleep 1
    ip -4 -o addr show dev "$iface" scope global 2>/dev/null \
        | awk '{print $4}' | grep -qxF "${ip_addr}/${prefix}" \
        || { error "未检测到预期地址 ${ip_addr}/${prefix}；自动回滚仍在计时"; return 1; }
    info "$iface 的静态 IPv4 已应用"
    audit_action "配置网卡 $iface ${ip_addr}/${prefix}" SUCCESS
    safety_confirm
}

network_dhcp_configure() {
    local iface backend
    print_header "设置 IPv4 DHCP"
    network_select_interface
    case "$?" in 0) ;; 2) return 0 ;; *) return 1 ;; esac
    iface="$NETWORK_SELECTED_IFACE"
    backend=$(network_backend_detect "$iface" 2>/dev/null || true)
    [ -n "$backend" ] || { error "无法识别 $iface 的网络配置后端"; return 1; }
    confirm_change_preview "设置 $iface 使用 DHCP" \
        "后端：$(network_backend_label "$backend")" "IPv4 地址、网关和 DNS 将由 DHCP 获取" \
        "应用后必须从新终端确认连接，否则 180 秒后自动恢复" || { warn "已取消"; return 0; }
    NETWORK_ROLLBACK_BACKEND="$backend"
    NETWORK_ROLLBACK_IFACE="$iface"
    NETWORK_ROLLBACK_NM_UUID=""
    [ "$backend" != networkmanager ] \
        || NETWORK_ROLLBACK_NM_UUID=$(network_nm_connection_uuid "$iface" 2>/dev/null || true)
    safety_arm network_interface || return 1
    case "$backend" in
        netplan) network_netplan_write_dhcp "$iface" ;;
        networkmanager) network_nm_write_dhcp "$iface" ;;
        networkd) network_networkd_write_dhcp "$iface" ;;
        ifupdown) network_ifupdown_write_dhcp "$iface" ;;
        ifcfg) network_ifcfg_write "$iface" dhcp ;;
    esac || { error "写入 DHCP 配置失败；自动回滚仍在计时"; return 1; }
    network_backend_validate "$backend" "$iface" \
        || { error "DHCP 配置校验失败；自动回滚仍在计时"; return 1; }
    network_backend_apply "$backend" "$iface" \
        || { error "应用 DHCP 配置失败；请保持旧会话，自动回滚仍在计时"; return 1; }
    sleep 2
    [ -n "$(network_current_ipv4_cidr "$iface")" ] \
        || { error "DHCP 尚未取得 IPv4 地址；自动回滚仍在计时"; return 1; }
    info "$iface 已切换为 DHCP"
    audit_action "网卡 $iface 切换 DHCP" SUCCESS
    safety_confirm
}

network_interface_menu() {
    while true; do
        print_header "网卡管理"
        menu_item "1" "查看网卡、IP、网关与 DNS"
        menu_item "2" "新增 / 修改静态 IPv4" "$YELLOW"
        menu_item "3" "设置 IPv4 DHCP" "$CYAN"
        menu_item "0" "返回主菜单" "$RED"
        menu_div
        ui_hint "支持 Netplan、NetworkManager、systemd-networkd、ifupdown 与 CentOS/RHEL ifcfg"
        ui_hint "远程修改网卡有断联风险，请始终保留当前 SSH 会话并另开终端验证"
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-3]: ')" choice
        case "$choice" in
            1) network_show_interfaces ;;
            2) network_static_configure ;;
            3) network_dhcp_configure ;;
            0) return ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac
        ui_pause
    done
}
# ══════════════════════════════════════════════════════════
#  Caddy 模块
# ══════════════════════════════════════════════════════════

CADDYFILE="/etc/caddy/Caddyfile"
CADDY_LOG="/var/log/caddy/access.log"

# ── 检测 Caddy 状态 ───────────────────────────────────────
caddy_status() {
    if ! command -v caddy &>/dev/null; then
        echo "not_installed"
    elif svc_is_active caddy; then
        echo "running"
    else
        echo "stopped"
    fi
}

# ── 安装后初始化 ──────────────────────────────────────────

caddy_post_install() {
    mkdir -p /etc/caddy /var/log/caddy
    if [ ! -f "$CADDYFILE" ]; then
        cat > "$CADDYFILE" << 'CEOF'
# Caddy 配置文件 — 由 VPS 开荒脚本生成
# 文档：https://caddyserver.com/docs/caddyfile

# 反向代理示例：
# example.com {
#     reverse_proxy localhost:8080
# }

# 静态网站示例：
# example.com {
#     root * /var/www/html
#     file_server
# }
CEOF
        info "已创建默认 Caddyfile：$CADDYFILE"
    fi
    command -v caddy >/dev/null 2>&1 || { error "Caddy 可执行文件不存在"; return 1; }
    svc_enable caddy
    if ! svc_start caddy && ! caddy start --config "$CADDYFILE" &>/dev/null; then
        error "Caddy 启动失败"
        return 1
    fi
    info "Caddy 已启动 ✓"
}

# ── 安装 Caddy（apt/apk/yum/二进制）─────────────────────
caddy_install() {
    print_header "安装 Caddy"
    info "开始安装 Caddy..."
    echo ""

    if command -v apt-get &>/dev/null; then
        apt-get install -y debian-keyring debian-archive-keyring apt-transport-https curl &>/dev/null
        curl -fsSL https://dl.cloudsmith.io/public/caddy/stable/gpg.key \
            | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg 2>/dev/null
        curl -fsSL https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt \
            | tee /etc/apt/sources.list.d/caddy-stable.list &>/dev/null
        apt-get update -qq &>/dev/null
        if apt-get install -y caddy 2>/dev/null; then info "Caddy 安装成功 ✓"; else caddy_install_binary || return 1; fi
    elif command -v apk &>/dev/null; then
        if apk add --no-cache caddy 2>/dev/null; then info "Caddy 安装成功 ✓"; else caddy_install_binary || return 1; fi
    elif command -v yum &>/dev/null; then
        yum install -y yum-plugin-copr &>/dev/null
        yum copr enable @caddy/caddy -y &>/dev/null
        if yum install -y caddy 2>/dev/null; then info "Caddy 安装成功 ✓"; else caddy_install_binary || return 1; fi
    elif command -v dnf &>/dev/null; then
        dnf install -y yum-plugin-copr &>/dev/null
        dnf copr enable @caddy/caddy -y &>/dev/null
        if dnf install -y caddy 2>/dev/null; then info "Caddy 安装成功 ✓"; else caddy_install_binary || return 1; fi
    else
        caddy_install_binary || return 1
    fi

    caddy_post_install
}

# 二进制安装（通用回退）
caddy_install_binary() {
    info "从 GitHub 下载 Caddy 二进制..."
    local ARCH; ARCH=$(uname -m)
    case "$ARCH" in
        x86_64)  ARCH="amd64" ;;
        aarch64) ARCH="arm64" ;;
        armv7l)  ARCH="armv7" ;;
        *) error "不支持的架构：$ARCH"; return 1 ;;
    esac

    local TMP; TMP=$(mktemp -d 2>/dev/null || { mkdir -p "/tmp/caddy_tmp_$$" && echo "/tmp/caddy_tmp_$$"; })
    local URL="https://github.com/caddyserver/caddy/releases/latest/download/caddy_linux_${ARCH}.tar.gz"

    if curl -fsSL "$URL" -o "$TMP/caddy.tar.gz"; then
        tar -xzf "$TMP/caddy.tar.gz" -C "$TMP" || { rm -rf "$TMP"; error "Caddy 压缩包解压失败"; return 1; }
        [ -f "$TMP/caddy" ] || { rm -rf "$TMP"; error "Caddy 压缩包缺少可执行文件"; return 1; }
        install -m 755 "$TMP/caddy" /usr/local/bin/caddy || { rm -rf "$TMP"; error "Caddy 安装失败"; return 1; }
        rm -rf "$TMP"
        info "Caddy 二进制安装到 /usr/local/bin/caddy ✓"
    else
        rm -rf "$TMP"
        error "下载失败，请检查网络"
        return 1
    fi

    # 创建 systemd service
    if systemd_available; then
        useradd -r -d /var/lib/caddy -s /sbin/nologin caddy 2>/dev/null || true
        cat > /etc/systemd/system/caddy.service << 'SVCEOF'
[Unit]
Description=Caddy Web Server
After=network.target

[Service]
User=caddy
Group=caddy
ExecStart=/usr/local/bin/caddy run --config /etc/caddy/Caddyfile
ExecReload=/usr/local/bin/caddy reload --config /etc/caddy/Caddyfile
TimeoutStopSec=5s
LimitNOFILE=1048576
PrivateTmp=true
ProtectSystem=full
AmbientCapabilities=CAP_NET_BIND_SERVICE

[Install]
WantedBy=multi-user.target
SVCEOF
        svc_daemon_reload
    fi
}

# ── 卸载 Caddy ────────────────────────────────────────────
caddy_uninstall() {
    print_header "卸载 Caddy"
    warn "即将卸载 Caddy（配置文件保留）"
    echo ""
    read -rp "  确认卸载？(Y/n，默认Y): " CONFIRM
    [ -z "${CONFIRM}" ] && CONFIRM="y"
    if ! echo "${CONFIRM}" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi
    svc_stop caddy || true
    svc_disable caddy
    pkg_remove caddy 2>/dev/null
    rm -f /usr/local/bin/caddy /etc/systemd/system/caddy.service
    svc_daemon_reload
    info "Caddy 已卸载 ✓（配置文件已保留）"
}

# ── 重载配置 ──────────────────────────────────────────────
# 安全追加 Caddy 配置块：先备份 → 追加 → validate，失败则还原，不污染正式配置
caddy_append_safe() {
    local BLOCK="$1"
    local TMP
    mkdir -p "$(dirname "$CADDYFILE")" || return 1
    TMP=$(mktemp "${CADDYFILE}.tmp.XXXXXX") || return 1
    if [ -f "$CADDYFILE" ]; then
        cp "$CADDYFILE" "$TMP" || { rm -f "$TMP"; return 1; }
    else
        : > "$TMP"
    fi
    printf '%s\n' "$BLOCK" >> "$TMP" || { rm -f "$TMP"; return 1; }
    if caddy validate --config "$TMP" 2>/tmp/caddy_err; then
        mv "$TMP" "$CADDYFILE" || { rm -f "$TMP"; return 1; }
        return 0
    fi
    rm -f "$TMP"
    error "新配置验证失败，已还原（未写入）："
    while IFS= read -r l; do echo -e "  ${RED}$l${NC}"; done < /tmp/caddy_err
    return 1
}

caddy_reload_config() {
    echo ""
    info "验证 Caddyfile 语法..."
    if caddy validate --config "$CADDYFILE" 2>/tmp/caddy_err; then
        info "语法验证通过 ✓"
        if svc_is_active caddy; then
            caddy reload --config "$CADDYFILE" 2>/dev/null || { error "Caddy 配置重载失败"; return 1; }
            info "配置已重载 ✓"
        else
            if ! svc_start caddy && ! caddy start --config "$CADDYFILE" &>/dev/null; then
                error "Caddy 启动失败"
                return 1
            fi
            info "Caddy 已启动 ✓"
        fi
    else
        error "Caddyfile 语法错误："
        while IFS= read -r l; do echo -e "  ${RED}$l${NC}"; done < /tmp/caddy_err
        return 1
    fi
}

# 输出 Caddyfile 中的站点与关键指令。只把顶层块识别为站点，避免把使用
# Tab 缩进的 reverse_proxy/header_up/transport 子块误列为独立站点。
caddy_site_records() {
    [ -f "$CADDYFILE" ] || return 0
    awk '
        function trim(value) {
            sub(/^[[:space:]]+/, "", value)
            sub(/[[:space:]]+$/, "", value)
            return value
        }
        function without_comment(value) {
            sub(/[[:space:]]+#.*$/, "", value)
            return value
        }
        {
            line = trim(without_comment($0))
            if (line == "" || line ~ /^#/) next

            opens = (line ~ /\{[[:space:]]*$/) ? 1 : 0
            closes = (line ~ /^\}/) ? 1 : 0

            if (depth == 0 && opens) {
                header = line
                sub(/[[:space:]]*\{[[:space:]]*$/, "", header)
                header = trim(header)
                active_site = (header != "" && header !~ /^\([^)]*\)$/)
                if (active_site) print "site\t" header
            } else if (depth > 0 && active_site) {
                directive = line
                sub(/[[:space:]].*$/, "", directive)
                if (directive ~ /^(reverse_proxy|root|file_server|redir)$/) {
                    target = line
                    sub(/^[^[:space:]]+[[:space:]]*/, "", target)
                    sub(/[[:space:]]*\{[[:space:]]*$/, "", target)
                    print "directive\t" directive "\t" trim(target)
                }
            }

            depth += opens - closes
            if (depth <= 0) {
                depth = 0
                active_site = 0
            }
        }
    ' "$CADDYFILE"
}

caddy_site_count() {
    caddy_site_records | awk -F '\t' '$1 == "site" { count++ } END { print count + 0 }'
}

# ── 查看所有站点 ──────────────────────────────────────────
caddy_list_sites() {
    print_header "当前 Caddy 站点"
    if [ ! -f "$CADDYFILE" ]; then warn "Caddyfile 不存在"; return; fi

    menu_div
    local i=0 kind value target
    while IFS=$'\t' read -r kind value target; do
        case "$kind" in
            site)
                [ "$i" -gt 0 ] && echo ""
                i=$((i+1))
                echo -e "  ${GREEN}[$i]${NC} ${BOLD}${value}${NC}"
                ;;
            directive)
                if [ -n "$target" ]; then
                    echo -e "      ${DIM}${value}${NC} → ${CYAN}${target}${NC}"
                else
                    echo -e "      ${DIM}${value}${NC}"
                fi
                ;;
        esac
    done < <(caddy_site_records)
    [ "$i" -gt 0 ] && echo ""
    [ "$i" -eq 0 ] && echo -e "  ${YELLOW}暂无站点配置${NC}\n"
    menu_div
}

# ── 添加反向代理站点 ──────────────────────────────────────
caddy_add_proxy() {
    print_header "添加反向代理站点"
    echo -e "  ${DIM}Caddy 会自动申请 SSL 证书（需域名已解析到本机）${NC}"
    echo ""
    read -rp "  域名（如 example.com 或 example.com:36366）: " DOMAIN
    [ -z "$DOMAIN" ] && { warn "已取消"; return; }
    read -rp "  转发到（如 127.0.0.1:8080）: " BACKEND
    [ -z "$BACKEND" ] && { warn "已取消"; return; }

    if grep -q "^${DOMAIN}" "$CADDYFILE" 2>/dev/null; then
        warn "域名 ${DOMAIN} 已存在，请先删除再添加"; return
    fi

    # 判断是否是带端口的域名（如 example.com:36366）
    local HAS_PORT=false
    local BARE_DOMAIN="$DOMAIN"
    if echo "$DOMAIN" | grep -qE '^[a-zA-Z0-9].*:[0-9]+$'; then
        HAS_PORT=true
        BARE_DOMAIN=$(echo "$DOMAIN" | cut -d: -f1)
    fi

    # 判断是否是域名（非 IP）
    local IS_DOMAIN=false
    if echo "$BARE_DOMAIN" | grep -qE '^[a-zA-Z0-9]([a-zA-Z0-9\-]*\.)+[a-zA-Z]{2,}$'; then
        IS_DOMAIN=true
    fi

    local SSL_LABEL CADDY_BLOCK
    if [ "$IS_DOMAIN" = true ]; then
        if [ "$HAS_PORT" = true ]; then
            # 带端口：检查裸域名站点是否存在（需先有裸域名才能复用证书）
            if grep -q "^${BARE_DOMAIN}" "$CADDYFILE" 2>/dev/null; then
                SSL_LABEL="${GREEN}复用 ${BARE_DOMAIN} 的证书 ✓${NC}"
            else
                SSL_LABEL="${YELLOW}注意：未找到 ${BARE_DOMAIN} 裸域名站点，建议先添加裸域名站点申请证书${NC}"
            fi
        else
            SSL_LABEL="${GREEN}自动 HTTPS（Let's Encrypt）${NC}"
        fi
        CADDY_BLOCK=$(printf '
%s {
    reverse_proxy %s
    encode gzip
}
' "$DOMAIN" "$BACKEND")
    else
        # IP 地址：不申请证书
        SSL_LABEL="${YELLOW}无 SSL（IP 地址无法申请证书）${NC}"
        CADDY_BLOCK=$(printf '
http://%s {
    reverse_proxy %s
}
' "$DOMAIN" "$BACKEND")
    fi

    echo ""
    menu_div
    echo -e "  域名 : ${BOLD}${DOMAIN}${NC}"
    echo -e "  后端 : ${BOLD}${BACKEND}${NC}"
    echo -e "  SSL  : ${SSL_LABEL}"
    menu_div
    echo ""
    read -rp "  确认添加？(Y/n，默认Y): " CONFIRM
    [ -z "${CONFIRM}" ] && CONFIRM="y"
    if ! echo "${CONFIRM}" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    if caddy_append_safe "$CADDY_BLOCK"; then
        caddy_reload_config && info "站点 ${DOMAIN} 已添加 ✓"
    fi
}

# ── 添加静态网站 ──────────────────────────────────────────
caddy_add_static() {
    print_header "添加静态网站"
    echo -e "  ${DIM}Caddy 会自动申请 SSL 证书（需域名已解析到本机）${NC}"
    echo ""
    read -rp "  域名（如 example.com 或 example.com:8443）: " DOMAIN
    [ -z "$DOMAIN" ] && { warn "已取消"; return; }
    read -rp "  网站根目录（默认 /var/www/html）: " WEBROOT
    WEBROOT="${WEBROOT:-/var/www/html}"

    if grep -q "^${DOMAIN}" "$CADDYFILE" 2>/dev/null; then
        warn "域名 ${DOMAIN} 已存在，请先删除再添加"; return
    fi

    local HAS_PORT=false
    local BARE_DOMAIN="$DOMAIN"
    if echo "$DOMAIN" | grep -qE '^[a-zA-Z0-9].*:[0-9]+$'; then
        HAS_PORT=true
        BARE_DOMAIN=$(echo "$DOMAIN" | cut -d: -f1)
    fi

    local IS_DOMAIN=false
    if echo "$BARE_DOMAIN" | grep -qE '^[a-zA-Z0-9]([a-zA-Z0-9\-]*\.)+[a-zA-Z]{2,}$'; then
        IS_DOMAIN=true
    fi

    local SSL_LABEL CADDY_BLOCK
    if [ "$IS_DOMAIN" = true ]; then
        if [ "$HAS_PORT" = true ]; then
            SSL_LABEL="${GREEN}复用 ${BARE_DOMAIN} 证书（需先添加裸域名站点申请证书）${NC}"
        else
            SSL_LABEL="${GREEN}自动 HTTPS（Let's Encrypt）${NC}"
        fi
        CADDY_BLOCK=$(printf '
%s {
    root * %s
    file_server
}
' "$DOMAIN" "$WEBROOT")
    else
        SSL_LABEL="${YELLOW}无 SSL（IP 地址无法申请证书）${NC}"
        CADDY_BLOCK=$(printf '
http://%s {
    root * %s
    file_server
}
' "$DOMAIN" "$WEBROOT")
    fi

    echo ""
    menu_div
    echo -e "  域名 : ${BOLD}${DOMAIN}${NC}"
    echo -e "  目录 : ${BOLD}${WEBROOT}${NC}"
    echo -e "  SSL  : ${SSL_LABEL}"
    menu_div
    echo ""
    read -rp "  确认添加？(Y/n，默认Y): " CONFIRM
    [ -z "${CONFIRM}" ] && CONFIRM="y"
    if ! echo "${CONFIRM}" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    mkdir -p "$WEBROOT"
    if caddy_append_safe "$CADDY_BLOCK"; then
        caddy_reload_config && info "静态站点 ${DOMAIN} 已添加 ✓"
    fi
}

# ── 删除站点 ──────────────────────────────────────────────
caddy_del_site() {
    print_header "删除站点"
    caddy_list_sites

    # 收集所有站点
    local SITES=()
    local kind value
    while IFS=$'\t' read -r kind value; do
        [ "$kind" = "site" ] && SITES+=("$value")
    done < <(caddy_site_records)

    if [ ${#SITES[@]} -eq 0 ]; then warn "暂无站点配置"; return; fi

    echo ""
    local i=1
    for site in "${SITES[@]}"; do
        echo -e "  ${GREEN}[$i]${NC} ${BOLD}${site}${NC}"
        i=$((i+1))
    done
    echo ""
    menu_div
    read -rp "  请输入编号删除（直接回车取消）: " NUM
    [ -z "$NUM" ] && { warn "已取消"; return; }
    if ! echo "$NUM" | grep -qE '^[0-9]+$' || [ "$NUM" -lt 1 ] || [ "$NUM" -gt ${#SITES[@]} ]; then
        error "无效编号"; return
    fi
    local DOMAIN="${SITES[$((NUM-1))]}"
    echo ""
    warn "即将删除站点：${BOLD}${DOMAIN}${NC}"
    read -rp "  确认删除？(Y/n，默认Y): " CONFIRM
    [ -z "${CONFIRM}" ] && CONFIRM="y"
    if ! echo "${CONFIRM}" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    local TMP BAK
    TMP=$(mktemp "${CADDYFILE}.tmp.XXXXXX") || return 1
    BAK="${CADDYFILE}.bak.$(date +%Y%m%d_%H%M%S)"
    if ! python3 - "$CADDYFILE" "$TMP" "$DOMAIN" << 'PYEOF'
import sys
path, output, site_header = sys.argv[1], sys.argv[2], sys.argv[3]
with open(path) as f:
    lines = f.readlines()

def syntax_line(line):
    line = line.strip()
    if " #" in line:
        line = line.split(" #", 1)[0].rstrip()
    return line

def block_delta(line):
    return int(line.endswith("{")) - int(line.startswith("}"))

result = []
skip = False
depth = 0
found = False
for line in lines:
    s = syntax_line(line)
    opening_header = s[:-1].strip() if s.endswith("{") else ""
    if not skip and depth == 0 and opening_header == site_header:
        skip = True
        found = True
        depth = 1
        while result and result[-1].strip() == '':
            result.pop()
        continue
    if skip:
        depth += block_delta(s)
        if depth <= 0:
            skip = False
            depth = 0
        continue
    result.append(line)
    depth += block_delta(s)
    if depth < 0:
        depth = 0
if not found:
    raise SystemExit(2)
with open(output, 'w') as f:
    f.writelines(result)
PYEOF
    then
        rm -f "$TMP"
        error "无法生成删除后的 Caddy 配置"
        return 1
    fi
    if ! caddy validate --config "$TMP" 2>/tmp/caddy_err; then
        rm -f "$TMP"
        error "删除后的 Caddy 配置验证失败，原配置未修改"
        return 1
    fi
    cp "$CADDYFILE" "$BAK" || { rm -f "$TMP"; return 1; }
    mv "$TMP" "$CADDYFILE" || { rm -f "$TMP"; return 1; }
    if caddy_reload_config; then
        rm -f "$BAK"
        info "站点 ${DOMAIN} 已删除 ✓"
    else
        cp "$BAK" "$CADDYFILE" 2>/dev/null || true
        rm -f "$BAK"
        caddy_reload_config >/dev/null 2>&1 || true
        error "站点删除应用失败，已恢复原配置"
        return 1
    fi
}

# ── SSL 证书状态 ──────────────────────────────────────────
caddy_ssl_status() {
    print_header "SSL 证书状态"
    echo -e "  ${DIM}Caddy 自动管理证书，首次访问时自动申请${NC}"
    echo ""

    local CERT_DIR=""
    for d in /var/lib/caddy/.local/share/caddy/certificates \
              /root/.local/share/caddy/certificates \
              /home/caddy/.local/share/caddy/certificates; do
        [ -d "$d" ] && CERT_DIR="$d" && break
    done

    if [ -z "$CERT_DIR" ]; then
        warn "未找到证书目录（证书将在首次访问时自动申请）"
        return
    fi

    echo -e "  证书目录：${DIM}${CERT_DIR}${NC}"
    menu_div
    find "$CERT_DIR" -name "*.crt" 2>/dev/null | while read -r cert; do
        local DN; DN=$(basename "$(dirname "$cert")")
        local EXP; EXP=$(openssl x509 -enddate -noout -in "$cert" 2>/dev/null | cut -d= -f2)
        echo -e "  ${GREEN}▸${NC} ${BOLD}${DN}${NC}"
        [ -n "$EXP" ] && echo -e "    ${DIM}到期：${NC}${EXP}"
    done
    menu_div
}

# ── 查看访问日志 ──────────────────────────────────────────
caddy_view_logs() {
    print_header "Caddy 访问日志"
    local LOG_FILE="$CADDY_LOG"
    [ ! -f "$LOG_FILE" ] && LOG_FILE=$(find /var/log/caddy /var/log -name "*.log" 2>/dev/null | grep -i caddy | head -1)

    if [ -z "$LOG_FILE" ] || [ ! -f "$LOG_FILE" ]; then
        if command -v journalctl &>/dev/null; then
            echo -e "  ${DIM}使用 journalctl${NC}"
            echo ""
            journalctl -u caddy -n 50 --no-pager 2>/dev/null | while IFS= read -r line; do
                echo -e "  $line"
            done
            echo ""
            menu_item "1" "开启实时跟踪  ${DIM}Ctrl+C 返回${NC}"
            menu_item "0" "返回上级" "$RED"
            echo ""
            read -rp "$(ui_prompt '选择操作: ')" _CH
            if [ "$_CH" = "1" ]; then
                trap 'echo ""; info "已退出实时跟踪"; trap - INT' INT
                journalctl -u caddy -f 2>/dev/null
                trap - INT
            fi
        else
            warn "未找到 Caddy 日志文件，请确认 Caddyfile 中已配置 log 指令"
        fi
        return
    fi

    echo -e "  ${DIM}${LOG_FILE}${NC}"
    menu_div
    echo ""
    tail -n 30 "$LOG_FILE" 2>/dev/null | while IFS= read -r line; do
        local STATUS; STATUS=$(echo "$line" | python3 -c \
            "import sys,json
try:
    d=json.loads(sys.stdin.read())
    print(d.get('status',''))
except: print('')" 2>/dev/null)
        if [ -n "$STATUS" ]; then
            local SC="$GREEN"
            [ "$STATUS" -ge 400 ] 2>/dev/null && SC="$YELLOW"
            [ "$STATUS" -ge 500 ] 2>/dev/null && SC="$RED"
            local TS METHOD URI
            TS=$(echo "$line" | python3 -c \
                "import sys,json
try:
    d=json.loads(sys.stdin.read())
    print(d.get('ts','')[:19].replace('T',' '))
except: print('')" 2>/dev/null)
            METHOD=$(echo "$line" | python3 -c \
                "import sys,json
try:
    d=json.loads(sys.stdin.read())
    print(d.get('request',{}).get('method',''))
except: print('')" 2>/dev/null)
            URI=$(echo "$line" | python3 -c \
                "import sys,json
try:
    d=json.loads(sys.stdin.read())
    print(d.get('request',{}).get('uri',''))
except: print('')" 2>/dev/null)
            echo -e "  ${DIM}${TS}${NC} ${BOLD}${METHOD}${NC} ${URI} ${SC}${STATUS}${NC}"
        else
            echo -e "  $line"
        fi
    done
    echo ""
    menu_div
    menu_item "1" "开启实时跟踪  ${DIM}Ctrl+C 返回${NC}"
    menu_item "0" "返回上级" "$RED"
    echo ""
    read -rp "$(ui_prompt '选择操作: ')" _CH
    if [ "$_CH" = "1" ]; then
        trap 'echo ""; info "已退出实时跟踪"; trap - INT' INT
        tail -f "$LOG_FILE" 2>/dev/null | while IFS= read -r line; do echo -e "  $line"; done
        trap - INT
    fi
}

# ── 编辑 Caddyfile ────────────────────────────────────────
caddy_edit_raw() {
    print_header "编辑 Caddyfile"
    echo -e "  配置文件：${BOLD}${CADDYFILE}${NC}"
    echo ""
    warn "$(get_editor) 打开 Caddyfile，保存退出后自动验证并重载"
    echo ""
    ui_continue
    [ -f "$CADDYFILE" ] || { mkdir -p /etc/caddy; touch "$CADDYFILE"; }
    local BAK
    BAK="${CADDYFILE}.bak.$(date +%Y%m%d_%H%M%S)"
    cp "$CADDYFILE" "$BAK" || { error "无法备份 Caddyfile"; return 1; }
    open_editor "$CADDYFILE"
    echo ""
    if caddy_reload_config; then
        rm -f "$BAK"
    else
        cp "$BAK" "$CADDYFILE" 2>/dev/null || true
        rm -f "$BAK"
        error "编辑后的配置无效，已恢复原文件"
        return 1
    fi
}

# ── Caddy 主菜单 ──────────────────────────────────────────
caddy_menu() {
    while true; do
        local C_ST; C_ST=$(caddy_status)
        local C_COLOR
        case "$C_ST" in
            running)       C_COLOR="$GREEN" ;;
            stopped)       C_COLOR="$RED" ;;
            not_installed) C_COLOR="$YELLOW" ;;
        esac

        print_header "Caddy 管理"

        if [ "$C_ST" = "not_installed" ]; then
            echo -e "  服务状态: ${C_COLOR}${BOLD}未安装${NC}"
            echo ""
            echo -e "  ${DIM}Caddy 是一个自动 HTTPS 的现代 Web 服务器，支持反向代理和静态托管${NC}"
            echo ""
            menu_div
            menu_item "1" "立即安装 Caddy"
            menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
            menu_div
            echo ""
            read -rp "$(ui_prompt '选择操作 [0-1]: ')" CH
            case "$CH" in
                1) caddy_install; ui_continue ;;
                0) return ;;
                00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                *) warn "无效选项"; sleep 1 ;;
            esac
            continue
        fi

        local C_VER; C_VER=$(caddy version 2>/dev/null | awk '{print $1}')
        local SITE_COUNT; SITE_COUNT=$(caddy_site_count)

        echo -e "  服务: ${C_COLOR}${BOLD}${C_ST}${NC}  版本: ${BOLD}${C_VER:-未知}${NC}  站点数: ${BOLD}${SITE_COUNT}${NC}"
        echo ""
        menu_div
        menu_pair "1" "查看站点" "2" "添加反向代理"
        menu_pair "3" "添加静态网站" "4" "删除站点"
        menu_pair "5" "SSL 证书状态" "6" "查看日志"
        menu_pair "7" "编辑 Caddyfile" "8" "重载配置"
        if [ "$C_ST" = "running" ]; then
            menu_item "9" "停止服务" "$YELLOW"
        else
            menu_item "9" "启动服务"
        fi
        menu_pair "u" "安装 / 更新" "d" "卸载 Caddy" "$CYAN" "$YELLOW"
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作: ')" CH

        case "$CH" in
            1) caddy_list_sites ;;
            2) caddy_add_proxy ;;
            3) caddy_add_static ;;
            4) caddy_del_site ;;
            5) caddy_ssl_status ;;
            6) caddy_view_logs ;;
            7) caddy_edit_raw ;;
            8) caddy_reload_config ;;
            u|U)
                print_header "安装/更新 Caddy"
                info "正在更新 Caddy..."
                caddy_install
                local NEW_VER; NEW_VER=$(caddy version 2>/dev/null | awk '{print $1}')
                info "当前版本：${NEW_VER:-未知} ✓"
                ;;
            9)
                if [ "$C_ST" = "running" ]; then
                    svc_stop caddy
                    info "Caddy 已停止 ✓"
                else
                    svc_start caddy \
                        || caddy start --config "$CADDYFILE" &>/dev/null
                    info "Caddy 已启动 ✓"
                fi
                sleep 1; continue
                ;;
            d|D) caddy_uninstall ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac

        [ "${CH}" != "0" ] && ui_pause
    done
}
