TS_HTTPS_SERVICE_FILE="${TS_HTTPS_SERVICE_FILE:-/etc/systemd/system/vps-tools-https-time.service}"
TS_HTTPS_TIMER_FILE="${TS_HTTPS_TIMER_FILE:-/etc/systemd/system/vps-tools-https-time.timer}"
TS_HTTPS_INTERVAL_FILE="${TS_HTTPS_INTERVAL_FILE:-$VPS_DATA_DIR/https-time-sync.interval}"
TS_HTTPS_STATE_FILE="${TS_HTTPS_STATE_FILE:-$VPS_DATA_DIR/https-time-sync.state}"
TS_HTTPS_LOCK_FILE="${TS_HTTPS_LOCK_FILE:-$VPS_DATA_DIR/https-time-sync.lock}"
TS_HTTPS_CRON_MARKER="# VPS_TOOLS_HTTPS_TIME_SYNC"

timesync_menu() {
    while true; do
        print_header "时间同步 / 时区设置"

        # 当前状态
        local CUR_TZ CUR_TIME CUR_DATE NTP_STATUS HTTPS_STATUS
        CUR_TZ=$(timedatectl show --property=Timezone --value 2>/dev/null || cat /etc/timezone 2>/dev/null || echo "未知")
        CUR_TIME=$(date '+%Y-%m-%d %H:%M:%S')
        CUR_DATE=$(date '+%Z %z')

        # NTP 状态
        if timedatectl show --property=NTPSynchronized --value 2>/dev/null | grep -q "yes"; then
            NTP_STATUS="${GREEN}已同步${NC}"
        elif command -v chronyc &>/dev/null && chronyc tracking 2>/dev/null | grep -q "Leap status.*Normal"; then
            NTP_STATUS="${GREEN}已同步(chrony)${NC}"
        else
            NTP_STATUS="${YELLOW}未同步${NC}"
        fi
        HTTPS_STATUS=$(ts_https_schedule_summary)

        echo -e "  当前时区：${BOLD}${CUR_TZ}${NC}"
        echo -e "  当前时间：${BOLD}${CUR_TIME}${NC}  ${DIM}${CUR_DATE}${NC}"
        echo -e "  NTP状态 ：${NTP_STATUS}"
        echo -e "  HTTPS定时：${HTTPS_STATUS}"
        echo ""
        menu_div
        menu_item "1" "强制同步时间"
        menu_pair "2" "设置北京时区" "3" "同步并设为北京"
        menu_pair "4" "设置其他时区" "5" "开启 NTP 自动同步"
        menu_item "6" "立即 HTTPS 时间同步  ${DIM}UDP/123 受限时使用${NC}" "$CYAN"
        menu_item "7" "HTTPS 自动同步设置" "$GREEN"
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-7]: ')" CH

        case "$CH" in
            1) ts_sync_time ;;
            2) ts_set_beijing ;;
            3) ts_set_beijing; ts_sync_time ;;
            4) ts_set_custom_tz ;;
            5) ts_enable_ntp ;;
            6) ts_sync_https ;;
            7) ts_https_schedule_menu; continue ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac

        [ "${CH}" != "0" ] && ui_pause
    done
}

ts_https_date_epoch() {
    local HTTP_DATE="$1" WEEKDAY DAY MONTH YEAR CLOCK ZONE EXTRA MONTH_NUM DAY_NUM ISO EPOCH
    read -r WEEKDAY DAY MONTH YEAR CLOCK ZONE EXTRA <<< "$HTTP_DATE"
    [ -n "$WEEKDAY" ] && [ -z "$EXTRA" ] || return 1
    case "$DAY" in ''|*[!0-9]*) return 1 ;; esac
    case "$YEAR" in ''|*[!0-9]*) return 1 ;; esac
    [ "${#DAY}" -le 2 ] && [ "${#YEAR}" -eq 4 ] || return 1
    [ "${ZONE^^}" = "GMT" ] || return 1
    echo "$CLOCK" | grep -qE '^([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$' || return 1
    case "$MONTH" in
        Jan) MONTH_NUM=1 ;; Feb) MONTH_NUM=2 ;; Mar) MONTH_NUM=3 ;; Apr) MONTH_NUM=4 ;;
        May) MONTH_NUM=5 ;; Jun) MONTH_NUM=6 ;; Jul) MONTH_NUM=7 ;; Aug) MONTH_NUM=8 ;;
        Sep) MONTH_NUM=9 ;; Oct) MONTH_NUM=10 ;; Nov) MONTH_NUM=11 ;; Dec) MONTH_NUM=12 ;;
        *) return 1 ;;
    esac
    DAY_NUM=$((10#$DAY))
    [ "$DAY_NUM" -ge 1 ] && [ "$DAY_NUM" -le 31 ] || return 1
    printf -v ISO '%04d-%02d-%02d %s' "$YEAR" "$MONTH_NUM" "$DAY_NUM" "$CLOCK"
    EPOCH=$(date -u -d "$ISO" '+%s' 2>/dev/null || true)
    if ! echo "$EPOCH" | grep -qE '^[0-9]+$' && command -v python3 >/dev/null 2>&1; then
        EPOCH=$(python3 - "$ISO" <<'PYEOF'
from datetime import datetime, timezone
import sys

try:
    parsed = datetime.strptime(sys.argv[1], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
except ValueError:
    raise SystemExit(1)
print(int(parsed.timestamp()))
PYEOF
        ) || return 1
    fi
    echo "$EPOCH" | grep -qE '^[0-9]+$' || return 1
    printf '%s\n' "$EPOCH"
}

ts_epoch_utc() {
    local EPOCH="$1" RESULT
    echo "$EPOCH" | grep -qE '^[0-9]+$' || return 1
    RESULT=$(date -u -d "@$EPOCH" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)
    if [ -z "$RESULT" ] && command -v python3 >/dev/null 2>&1; then
        RESULT=$(python3 - "$EPOCH" <<'PYEOF'
from datetime import datetime, timezone
import sys

print(datetime.fromtimestamp(int(sys.argv[1]), timezone.utc).strftime("%Y-%m-%d %H:%M:%S"))
PYEOF
        ) || return 1
    fi
    [ -n "$RESULT" ] || return 1
    printf '%s\n' "$RESULT"
}

ts_https_fetch_epoch() {
    local URL="$1" HEADERS HTTP_DATE
    HEADERS=$(curl --proto '=https' -sS -I --connect-timeout 5 --max-time 8 \
        -H 'Cache-Control: no-cache' -H 'Pragma: no-cache' "$URL" 2>/dev/null) || return 1
    HTTP_DATE=$(printf '%s\n' "$HEADERS" | awk '
        tolower($0) ~ /^date:[[:space:]]/ {
            sub(/^[^:]*:[[:space:]]*/, "")
            sub(/\r$/, "")
            value=$0
        }
        END { if (value != "") print value }
    ')
    [ -n "$HTTP_DATE" ] || return 1
    ts_https_date_epoch "$HTTP_DATE"
}

ts_https_consensus() {
    local MAX_SKEW="${TS_HTTPS_MAX_SKEW:-10}" VALUE I J COUNT BEST_START=0 BEST_COUNT=0
    local FIRST LAST MID TARGET SPREAD
    local VALUES=()
    case "$MAX_SKEW" in ''|*[!0-9]*) MAX_SKEW=10 ;; esac
    [ "$MAX_SKEW" -ge 1 ] || MAX_SKEW=10
    for VALUE in "$@"; do
        echo "$VALUE" | grep -qE '^[0-9]+$' && VALUES+=("$VALUE")
    done
    [ "${#VALUES[@]}" -ge 2 ] || return 1
    mapfile -t VALUES < <(printf '%s\n' "${VALUES[@]}" | sort -n)

    for ((I=0; I<${#VALUES[@]}; I++)); do
        COUNT=0
        for ((J=I; J<${#VALUES[@]}; J++)); do
            [ $((VALUES[J] - VALUES[I])) -le "$MAX_SKEW" ] || break
            COUNT=$((COUNT + 1))
        done
        if [ "$COUNT" -gt "$BEST_COUNT" ]; then
            BEST_START=$I
            BEST_COUNT=$COUNT
        fi
    done
    [ "$BEST_COUNT" -ge 2 ] || return 1

    FIRST=${VALUES[BEST_START]}
    LAST=${VALUES[$((BEST_START + BEST_COUNT - 1))]}
    MID=$((BEST_START + BEST_COUNT / 2))
    if [ $((BEST_COUNT % 2)) -eq 0 ]; then
        TARGET=$(( (VALUES[MID - 1] + VALUES[MID]) / 2 ))
    else
        TARGET=${VALUES[MID]}
    fi
    SPREAD=$((LAST - FIRST))
    printf '%s %s %s\n' "$TARGET" "$BEST_COUNT" "$SPREAD"
}

ts_sync_https() {
    local MODE="${1:-standalone}" SOURCE LABEL URL EPOCH LOCAL_SAMPLE REFERENCE_LOCAL
    local CONSENSUS COUNT SPREAD TARGET_UTC BEFORE AFTER DRIFT ABS_DRIFT I
    local SOURCES=(
        'Cloudflare|https://www.cloudflare.com/'
        'Aliyun|https://www.aliyun.com/'
        'Microsoft|https://www.microsoft.com/'
        'GitHub|https://github.com/'
        'Google|https://www.google.com/generate_204'
    )
    local SAMPLE_EPOCHS=() SAMPLE_LOCALS=() ADJUSTED=()

    [ "$MODE" = standalone ] && print_header "HTTPS 时间同步"
    echo -e "  ${DIM}通过 TCP/443 获取多个 HTTPS Date 响应并校验时间共识${NC}"
    echo -e "  ${DIM}证书验证保持开启；至少两个来源需在 10 秒内一致${NC}"
    echo ""

    if ! command -v curl >/dev/null 2>&1; then
        error "缺少 curl，无法执行 HTTPS 时间同步"
        return 1
    fi

    for SOURCE in "${SOURCES[@]}"; do
        LABEL=${SOURCE%%|*}
        URL=${SOURCE#*|}
        if EPOCH=$(ts_https_fetch_epoch "$URL") \
            && echo "$EPOCH" | grep -qE '^[0-9]+$' \
            && [ "$EPOCH" -ge 1577836800 ] && [ "$EPOCH" -le 4102444799 ]; then
            LOCAL_SAMPLE=$(date '+%s')
            SAMPLE_EPOCHS+=("$EPOCH")
            SAMPLE_LOCALS+=("$LOCAL_SAMPLE")
            info "$LABEL：$(ts_epoch_utc "$EPOCH") UTC"
            [ "${#SAMPLE_EPOCHS[@]}" -ge 3 ] && break
        else
            warn "$LABEL：无法获取有效 HTTPS 时间"
        fi
    done

    if [ "${#SAMPLE_EPOCHS[@]}" -lt 2 ]; then
        error "有效 HTTPS 时间来源不足，至少需要 2 个"
        warn "若系统时间偏差过大，TLS 证书也可能无法验证；请先通过 VPS 控制台粗略校时"
        return 1
    fi

    REFERENCE_LOCAL=$(date '+%s')
    for ((I=0; I<${#SAMPLE_EPOCHS[@]}; I++)); do
        ADJUSTED+=("$((SAMPLE_EPOCHS[I] + REFERENCE_LOCAL - SAMPLE_LOCALS[I]))")
    done
    CONSENSUS=$(ts_https_consensus "${ADJUSTED[@]}") || {
        error "HTTPS 来源时间差异超过 10 秒，已拒绝修改系统时间"
        return 1
    }
    read -r EPOCH COUNT SPREAD <<< "$CONSENSUS"
    TARGET_UTC=$(ts_epoch_utc "$EPOCH") || { error "无法转换 HTTPS 时间"; return 1; }
    BEFORE=$(date '+%s')
    DRIFT=$((EPOCH - BEFORE))

    menu_div
    echo -e "  共识来源：${BOLD}${COUNT}${NC}  最大差异：${BOLD}${SPREAD} 秒${NC}"
    echo -e "  目标时间：${BOLD}${TARGET_UTC} UTC${NC}"
    echo -e "  本机偏差：${BOLD}${DRIFT} 秒${NC}"
    menu_div
    echo ""

    if ! date -u -s "$TARGET_UTC" >/dev/null 2>&1; then
        error "设置系统时间失败，当前环境可能缺少改时权限"
        return 1
    fi
    command -v hwclock >/dev/null 2>&1 && hwclock --systohc >/dev/null 2>&1 || true
    AFTER=$(date '+%s')
    ABS_DRIFT=$((AFTER - EPOCH)); ABS_DRIFT=${ABS_DRIFT#-}
    if [ "$ABS_DRIFT" -gt 5 ]; then
        error "设置后的系统时间校验失败，偏差 ${ABS_DRIFT} 秒"
        return 1
    fi

    info "HTTPS 时间同步成功 ✓"
    [ "$MODE" = fallback ] || info "当前时间：$(date '+%Y-%m-%d %H:%M:%S %Z')"
    [ "$MODE" = scheduled ] || info "可在时间菜单启用 HTTPS 自动同步"
    audit_action "HTTPS时间同步，${COUNT}个来源共识，偏差${DRIFT}秒" SUCCESS
    return 0
}

ts_https_interval_normalize() {
    case "${1:-}" in
        1|3|6|12|24) printf '%s\n' "$1" ;;
        *) return 1 ;;
    esac
}

ts_https_interval_current() {
    local VALUE
    VALUE=$(awk 'NR == 1 { print $1 }' "$TS_HTTPS_INTERVAL_FILE" 2>/dev/null || true)
    ts_https_interval_normalize "$VALUE" 2>/dev/null || printf '6\n'
}

ts_https_cron_expr() {
    local INTERVAL
    INTERVAL=$(ts_https_interval_normalize "$1") || return 1
    case "$INTERVAL" in
        1) printf '17 * * * *\n' ;;
        3) printf '17 */3 * * *\n' ;;
        6) printf '17 */6 * * *\n' ;;
        12) printf '17 */12 * * *\n' ;;
        24) printf '17 3 * * *\n' ;;
    esac
}

ts_https_cron_without_managed() {
    grep -Fv -- "$TS_HTTPS_CRON_MARKER"
}

ts_https_schedule_backend() {
    if command -v systemctl >/dev/null 2>&1 \
        && systemctl is-active --quiet "$(basename "$TS_HTTPS_TIMER_FILE")" 2>/dev/null; then
        printf 'systemd\n'
        return 0
    fi
    if command -v crontab >/dev/null 2>&1 \
        && crontab -l 2>/dev/null | grep -Fq -- "$TS_HTTPS_CRON_MARKER"; then
        printf 'cron\n'
        return 0
    fi
    return 1
}

ts_https_schedule_last_result() {
    [ -s "$TS_HTTPS_STATE_FILE" ] || return 1
    awk -F '\t' 'NR == 1 && NF >= 3 { printf "%s %s（%s）", $1, $2, $3 }' "$TS_HTTPS_STATE_FILE"
}

ts_https_schedule_summary() {
    local BACKEND INTERVAL
    BACKEND=$(ts_https_schedule_backend 2>/dev/null || true)
    [ -n "$BACKEND" ] || { printf '%s未启用%s' "$DIM" "$NC"; return; }
    INTERVAL=$(ts_https_interval_current)
    printf '%s每 %s 小时（%s）%s' "$GREEN" "$INTERVAL" "$BACKEND" "$NC"
}

ts_https_runner_valid() {
    self_script_valid "$LOCAL_SCRIPT" \
        && grep -qF -- '--https-time-sync-run)' "$LOCAL_SCRIPT" 2>/dev/null
}

ts_https_runner_path_valid() {
    case "$LOCAL_SCRIPT" in
        /*) ;;
        *) return 1 ;;
    esac
    case "$LOCAL_SCRIPT" in
        *[!A-Za-z0-9_./-]*) return 1 ;;
    esac
}

ts_https_ensure_runner() {
    local SOURCE
    ts_https_runner_path_valid || { error "本地脚本路径包含定时任务不支持的字符"; return 1; }
    ts_https_runner_valid && return 0
    SOURCE=$(self_resolve_script_source "$0" 2>/dev/null || true)
    if [ -n "$SOURCE" ]; then
        self_atomic_replace "$SOURCE" "$LOCAL_SCRIPT" || { error "无法安装 HTTPS 定时任务执行脚本"; return 1; }
        chmod 755 "$LOCAL_SCRIPT" 2>/dev/null || true
    else
        info "定时任务需要本地完整脚本，正在安装..."
        self_install || return 1
    fi
    ts_https_runner_valid || { error "本地脚本缺少 HTTPS 定时任务入口"; return 1; }
}

ts_https_scheduled_run() {
    local OUTPUT STATUS RC STATE_TMP LOCK_DIR="" LOCK_PID="" LOCK_FD_OPEN=no
    mkdir -p "$VPS_DATA_DIR" 2>/dev/null || return 1
    chmod 700 "$VPS_DATA_DIR" 2>/dev/null || true
    if command -v flock >/dev/null 2>&1; then
        exec 9>"$TS_HTTPS_LOCK_FILE"
        if ! flock -n 9; then
            exec 9>&-
            return 0
        fi
        LOCK_FD_OPEN=yes
    else
        LOCK_DIR="${TS_HTTPS_LOCK_FILE}.d"
        if ! mkdir "$LOCK_DIR" 2>/dev/null; then
            LOCK_PID=$(cat "$LOCK_DIR/pid" 2>/dev/null || true)
            if echo "$LOCK_PID" | grep -qE '^[0-9]+$' && ! kill -0 "$LOCK_PID" 2>/dev/null; then
                rm -rf "$LOCK_DIR"
                mkdir "$LOCK_DIR" 2>/dev/null || return 0
            else
                return 0
            fi
        fi
        printf '%s\n' "$$" > "$LOCK_DIR/pid"
    fi
    if OUTPUT=$(ts_sync_https scheduled 2>&1); then
        STATUS=成功
        RC=0
    else
        STATUS=失败
        RC=1
    fi
    STATE_TMP="${TS_HTTPS_STATE_FILE}.tmp.$$"
    if printf '%s\t%s\t%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$STATUS" "HTTPS" > "$STATE_TMP"; then
        chmod 600 "$STATE_TMP" 2>/dev/null || true
        mv -f "$STATE_TMP" "$TS_HTTPS_STATE_FILE" || true
    fi
    if command -v logger >/dev/null 2>&1; then
        printf '%s\n' "$OUTPUT" | logger -t vps-tools-https-time
    fi
    if [ "$RC" -eq 0 ]; then
        audit_action "HTTPS定时同步成功" SUCCESS
    else
        audit_action "HTTPS定时同步失败" FAILED
    fi
    [ -n "$LOCK_DIR" ] && rm -rf "$LOCK_DIR"
    if [ "$LOCK_FD_OPEN" = yes ]; then
        flock -u 9 2>/dev/null || true
        exec 9>&-
    fi
    return "$RC"
}

ts_https_schedule_enable_systemd() {
    local INTERVAL="$1" SERVICE_TMP TIMER_TMP
    SERVICE_TMP="${TS_HTTPS_SERVICE_FILE}.tmp.$$"
    TIMER_TMP="${TS_HTTPS_TIMER_FILE}.tmp.$$"
    cat > "$SERVICE_TMP" <<EOF
[Unit]
Description=VPS Tools HTTPS time synchronization
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$LOCAL_SCRIPT --https-time-sync-run
TimeoutStartSec=60
EOF
    cat > "$TIMER_TMP" <<EOF
[Unit]
Description=Run VPS Tools HTTPS time synchronization every ${INTERVAL} hours

[Timer]
OnActiveSec=1min
OnUnitActiveSec=${INTERVAL}h
AccuracySec=1min
RandomizedDelaySec=2min
Persistent=true
Unit=$(basename "$TS_HTTPS_SERVICE_FILE")

[Install]
WantedBy=timers.target
EOF
    chmod 644 "$SERVICE_TMP" "$TIMER_TMP"
    mv -f "$SERVICE_TMP" "$TS_HTTPS_SERVICE_FILE" \
        && mv -f "$TIMER_TMP" "$TS_HTTPS_TIMER_FILE" \
        || { rm -f "$SERVICE_TMP" "$TIMER_TMP"; return 1; }
    if ! systemctl daemon-reload >/dev/null 2>&1 \
        || ! systemctl enable "$(basename "$TS_HTTPS_TIMER_FILE")" >/dev/null 2>&1 \
        || ! systemctl restart "$(basename "$TS_HTTPS_TIMER_FILE")" >/dev/null 2>&1; then
        systemctl disable --now "$(basename "$TS_HTTPS_TIMER_FILE")" >/dev/null 2>&1 || true
        rm -f "$TS_HTTPS_SERVICE_FILE" "$TS_HTTPS_TIMER_FILE"
        systemctl daemon-reload >/dev/null 2>&1 || true
        return 1
    fi
}

ts_https_schedule_enable_cron() {
    local INTERVAL="$1" EXPR CURRENT CRON_TMP
    command -v crontab >/dev/null 2>&1 || return 1
    EXPR=$(ts_https_cron_expr "$INTERVAL") || return 1
    CURRENT=$(crontab -l 2>/dev/null || true)
    CRON_TMP=$(mktemp "${TMPDIR:-/tmp}/vps-tools-time-cron.XXXXXX") || return 1
    {
        printf '%s\n' "$CURRENT" | ts_https_cron_without_managed || true
        printf '%s %s --https-time-sync-run >/dev/null 2>&1 %s\n' "$EXPR" "$LOCAL_SCRIPT" "$TS_HTTPS_CRON_MARKER"
    } | awk 'NF' > "$CRON_TMP"
    if ! crontab "$CRON_TMP"; then
        rm -f "$CRON_TMP"
        return 1
    fi
    rm -f "$CRON_TMP"
    if ! ts_https_cron_daemon_enable; then
        ts_https_schedule_remove_cron || true
        return 1
    fi
}

ts_https_cron_daemon_enable() {
    local SERVICE
    for SERVICE in cron crond; do
        svc_is_active "$SERVICE" 2>/dev/null && return 0
    done
    for SERVICE in cron crond; do
        if [ -x "/etc/init.d/$SERVICE" ]; then
            "/etc/init.d/$SERVICE" enable >/dev/null 2>&1 || true
            "/etc/init.d/$SERVICE" start >/dev/null 2>&1 && return 0
        fi
        svc_enable "$SERVICE" >/dev/null 2>&1 || true
        svc_start "$SERVICE" >/dev/null 2>&1 && return 0
    done
    command -v pgrep >/dev/null 2>&1 \
        && { pgrep -x cron >/dev/null 2>&1 || pgrep -x crond >/dev/null 2>&1; }
}

ts_https_schedule_remove_cron() {
    local CURRENT CRON_TMP
    command -v crontab >/dev/null 2>&1 || return 0
    CURRENT=$(crontab -l 2>/dev/null || true)
    printf '%s\n' "$CURRENT" | grep -Fq -- "$TS_HTTPS_CRON_MARKER" || return 0
    CRON_TMP=$(mktemp "${TMPDIR:-/tmp}/vps-tools-time-cron.XXXXXX") || return 1
    printf '%s\n' "$CURRENT" | ts_https_cron_without_managed | awk 'NF' > "$CRON_TMP" || true
    crontab "$CRON_TMP"
    rm -f "$CRON_TMP"
}

ts_https_schedule_enable() {
    local INTERVAL BACKEND
    INTERVAL=$(ts_https_interval_normalize "$1") || { error "不支持的同步周期"; return 1; }
    ts_https_ensure_runner || return 1
    mkdir -p "$(dirname "$TS_HTTPS_INTERVAL_FILE")" || return 1

    if systemd_available && command -v systemctl >/dev/null 2>&1; then
        ts_https_schedule_remove_cron || true
        if ! ts_https_schedule_enable_systemd "$INTERVAL"; then
            error "systemd timer 创建失败"
            return 1
        fi
        BACKEND=systemd
    else
        if ! ts_https_schedule_enable_cron "$INTERVAL"; then
            error "系统缺少可用的 systemd timer 或 crontab"
            return 1
        fi
        BACKEND=cron
    fi
    printf '%s\n' "$INTERVAL" > "$TS_HTTPS_INTERVAL_FILE"
    chmod 600 "$TS_HTTPS_INTERVAL_FILE" 2>/dev/null || true
    info "HTTPS 自动同步已启用：每 ${INTERVAL} 小时（${BACKEND}）"
    audit_action "启用HTTPS定时同步，每${INTERVAL}小时，${BACKEND}" SUCCESS
    if ts_https_scheduled_run; then
        info "首次 HTTPS 时间同步成功"
    else
        warn "定时任务已启用，但首次同步失败；系统将在下一周期重试"
    fi
}

ts_https_schedule_disable() {
    if command -v systemctl >/dev/null 2>&1; then
        systemctl disable --now "$(basename "$TS_HTTPS_TIMER_FILE")" >/dev/null 2>&1 || true
        systemctl stop "$(basename "$TS_HTTPS_SERVICE_FILE")" >/dev/null 2>&1 || true
    fi
    rm -f "$TS_HTTPS_TIMER_FILE" "$TS_HTTPS_SERVICE_FILE"
    command -v systemctl >/dev/null 2>&1 && systemctl daemon-reload >/dev/null 2>&1 || true
    ts_https_schedule_remove_cron || true
    rm -f "$TS_HTTPS_INTERVAL_FILE"
    info "HTTPS 自动同步已关闭"
    audit_action "关闭HTTPS定时同步" SUCCESS
}

ts_https_schedule_menu() {
    while true; do
        local BACKEND INTERVAL LAST CH
        BACKEND=$(ts_https_schedule_backend 2>/dev/null || true)
        INTERVAL=$(ts_https_interval_current)
        LAST=$(ts_https_schedule_last_result 2>/dev/null || true)
        print_header "HTTPS 自动同步"
        if [ -n "$BACKEND" ]; then
            echo -e "  状态：${GREEN}${BOLD}运行中${NC}  每 ${BOLD}${INTERVAL}${NC} 小时  ${DIM}${BACKEND}${NC}"
        else
            echo -e "  状态：${DIM}未启用${NC}"
        fi
        echo -e "  最近：${BOLD}${LAST:-暂无执行记录}${NC}"
        echo ""
        menu_div
        menu_pair "1" "每 1 小时" "2" "每 3 小时"
        menu_pair "3" "每 6 小时  推荐" "4" "每 12 小时" "$GREEN" "$CYAN"
        menu_pair "5" "每 24 小时" "6" "立即同步"
        menu_item "7" "关闭 HTTPS 自动同步" "$RED"
        menu_item "0" "返回上级" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-7]: ')" CH
        case "$CH" in
            1) ts_https_schedule_enable 1 ;;
            2) ts_https_schedule_enable 3 ;;
            3) ts_https_schedule_enable 6 ;;
            4) ts_https_schedule_enable 12 ;;
            5) ts_https_schedule_enable 24 ;;
            6) ts_sync_https ;;
            7) ts_https_schedule_disable ;;
            0) return ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac
        ui_pause
    done
}

# ── 强制同步时间 ──────────────────────────────────────────
ts_sync_time() {
    print_header "强制同步系统时间"
    echo -e "  ${DIM}尝试多种方式同步时间...${NC}"
    echo ""

    local SYNCED=false

    # 方法1：timedatectl + systemd-timesyncd
    if command -v timedatectl &>/dev/null && systemd_available; then
        info "尝试 systemd-timesyncd..."
        timedatectl set-ntp true 2>/dev/null
        # 重启 timesyncd 强制立即同步
        systemctl restart systemd-timesyncd 2>/dev/null
        sleep 2
        if timedatectl show --property=NTPSynchronized --value 2>/dev/null | grep -q "yes"; then
            info "systemd-timesyncd 同步成功 ✓"
            SYNCED=true
        fi
    fi

    # 方法2：chrony
    if [ "$SYNCED" = false ] && command -v chronyc &>/dev/null; then
        info "尝试 chrony..."
        systemctl restart chronyd 2>/dev/null || rc-service chronyd restart 2>/dev/null || true
        sleep 1
        chronyc makestep 2>/dev/null && info "chrony 强制同步成功 ✓" && SYNCED=true
    fi

    # 方法3：ntpdate（直连 NTP 服务器）
    if [ "$SYNCED" = false ]; then
        local NTP_SERVERS="ntp.aliyun.com time.cloudflare.com pool.ntp.org time.google.com"
        if command -v ntpdate &>/dev/null; then
            info "尝试 ntpdate..."
            for srv in $NTP_SERVERS; do
                if ntpdate -u "$srv" &>/dev/null; then
                    info "ntpdate 同步成功（$srv）✓"
                    SYNCED=true
                    break
                fi
            done
        else
            # 安装 ntpdate 再同步
            info "ntpdate 未安装，尝试安装..."
            pkg_install ntpdate &>/dev/null
            if command -v ntpdate &>/dev/null; then
                for srv in $NTP_SERVERS; do
                    if ntpdate -u "$srv" &>/dev/null; then
                        info "ntpdate 同步成功（$srv）✓"
                        SYNCED=true
                        break
                    fi
                done
            fi
        fi
    fi

    # 方法4：通过多个 HTTPS Date 响应建立共识，适用于 UDP/123 被封锁
    if [ "$SYNCED" = false ]; then
        info "尝试 HTTPS 多来源时间同步..."
        ts_sync_https fallback && SYNCED=true
    fi

    echo ""
    if [ "$SYNCED" = true ]; then
        info "当前时间：$(date '+%Y-%m-%d %H:%M:%S %Z')"
    else
        error "自动同步失败，请检查网络连接"
        echo -e "  ${DIM}可返回时间菜单选择 6，单独诊断 HTTPS 时间同步${NC}"
    fi
}

# ── 设置北京时区 ──────────────────────────────────────────
ts_set_beijing() {
    print_header "设置北京时区"
    info "设置时区为 Asia/Shanghai（北京 UTC+8）..."

    if command -v timedatectl &>/dev/null; then
        timedatectl set-timezone Asia/Shanghai 2>/dev/null && info "时区已设置 ✓"
    elif [ -f /usr/share/zoneinfo/Asia/Shanghai ]; then
        ln -sf /usr/share/zoneinfo/Asia/Shanghai /etc/localtime
        echo "Asia/Shanghai" > /etc/timezone
        info "时区已设置 ✓"
    else
        error "找不到时区文件，尝试安装 tzdata..."
        pkg_install tzdata &>/dev/null
        if [ -f /usr/share/zoneinfo/Asia/Shanghai ]; then
            ln -sf /usr/share/zoneinfo/Asia/Shanghai /etc/localtime
            echo "Asia/Shanghai" > /etc/timezone
            info "时区已设置 ✓"
        else
            error "设置失败，请手动执行：timedatectl set-timezone Asia/Shanghai"
            return
        fi
    fi

    echo ""
    info "当前时间：$(date '+%Y-%m-%d %H:%M:%S %Z %z')"
}

# ── 设置自定义时区 ────────────────────────────────────────
ts_set_custom_tz() {
    print_header "设置自定义时区"
    echo -e "  常用时区参考："
    echo -e "  ${GREEN}Asia/Shanghai${NC}       北京 UTC+8"
    echo -e "  ${GREEN}Asia/Tokyo${NC}          东京 UTC+9"
    echo -e "  ${GREEN}America/New_York${NC}    纽约 UTC-5"
    echo -e "  ${GREEN}America/Los_Angeles${NC} 洛杉矶 UTC-8"
    echo -e "  ${GREEN}Europe/London${NC}       伦敦 UTC+0"
    echo -e "  ${GREEN}Europe/Paris${NC}        巴黎 UTC+1"
    echo ""
    read -rp "  请输入时区名称（直接回车取消）: " TZ_INPUT
    [ -z "$TZ_INPUT" ] && { warn "已取消"; return; }

    if [ ! -f "/usr/share/zoneinfo/${TZ_INPUT}" ]; then
        error "时区 '${TZ_INPUT}' 不存在，请检查拼写"
        return
    fi

    if command -v timedatectl &>/dev/null; then
        timedatectl set-timezone "$TZ_INPUT" 2>/dev/null && info "时区已设置为 ${TZ_INPUT} ✓"
    else
        ln -sf "/usr/share/zoneinfo/${TZ_INPUT}" /etc/localtime
        echo "$TZ_INPUT" > /etc/timezone
        info "时区已设置为 ${TZ_INPUT} ✓"
    fi

    echo ""
    info "当前时间：$(date '+%Y-%m-%d %H:%M:%S %Z %z')"
}

# ── 开启 NTP 自动同步 ─────────────────────────────────────
ts_enable_ntp() {
    print_header "开启 NTP 自动同步"

    # 检测 CanNTP — 判断是否有 timesyncd
    local CAN_NTP
    CAN_NTP=$(timedatectl show --property=CanNTP --value 2>/dev/null || echo "no")

    if [ "$CAN_NTP" = "yes" ] && command -v systemctl &>/dev/null \
        && systemctl list-unit-files 2>/dev/null | grep -q '^systemd-timesyncd.service'; then
        # systemd-timesyncd 可用
        timedatectl set-ntp true 2>/dev/null || { error "无法启用系统 NTP"; return 1; }
        systemctl enable systemd-timesyncd --quiet 2>/dev/null || true
        systemctl restart systemd-timesyncd 2>/dev/null || { error "systemd-timesyncd 启动失败"; return 1; }
        systemctl is-active --quiet systemd-timesyncd 2>/dev/null || { error "systemd-timesyncd 未运行"; return 1; }
        info "systemd-timesyncd NTP 已开启 ✓"
    elif command -v chronyc &>/dev/null; then
        # chrony 已安装，自动探测服务名
        local CHRONY_SVC="chronyd"
        systemctl list-unit-files 2>/dev/null | grep -q "^chrony.service" && CHRONY_SVC="chrony"
        svc_enable "$CHRONY_SVC"
        svc_start "$CHRONY_SVC" || { error "chrony 启动失败"; return 1; }
        sleep 1
        chronyc makestep &>/dev/null && info "chrony 强制同步 ✓"
        info "chrony NTP 自动同步已开启 ✓"
    else
        # 都没有，安装 chrony
        info "正在安装 chrony..."
        if pkg_install chrony; then
            # Debian 服务名是 chrony，CentOS/Alpine 是 chronyd
            local CHRONY_SVC="chronyd"
            systemctl list-unit-files 2>/dev/null | grep -q "^chrony.service" && CHRONY_SVC="chrony"
            svc_enable "$CHRONY_SVC"
            svc_start "$CHRONY_SVC" || { error "chrony 启动失败"; return 1; }
            sleep 2
            chronyc makestep &>/dev/null && info "chrony 强制同步 ✓"
            info "chrony 已安装并开启自动同步 ✓"
        else
            error "chrony 安装失败，请手动执行：apt-get install -y chrony"
            return
        fi
    fi

    echo ""
    sleep 2
    # 验证同步状态
    local SYNC_ST
    SYNC_ST=$(timedatectl show --property=NTPSynchronized --value 2>/dev/null || echo "unknown")
    if [ "$SYNC_ST" = "yes" ]; then
        info "NTP 状态：已同步 ✓"
        info "当前时间：$(date '+%Y-%m-%d %H:%M:%S %Z')"
    else
        warn "NTP 状态：同步中（chrony 可能需要几秒完成首次同步）"
        # 尝试 chrony 状态
        if command -v chronyc &>/dev/null; then
            chronyc tracking 2>/dev/null | grep -E "Reference|System time|Last offset" | while IFS= read -r l; do
                echo -e "  ${DIM}$l${NC}"
            done
        fi
    fi
}
# ══════════════════════════════════════════════════════════
#  Swap 管理模块
# ══════════════════════════════════════════════════════════

# ── 显示当前 swap 状态 ────────────────────────────────────
swap_show_status() {
    echo -e "  ${BOLD}当前 Swap 状态：${NC}"
    local TOTAL USED FREE
    if swapon --show 2>/dev/null | grep -q .; then
        swapon --show --bytes 2>/dev/null | while IFS= read -r line; do
            echo -e "  ${CYAN}${line}${NC}"
        done
        echo ""
        TOTAL=$(free -m 2>/dev/null | awk '/^Swap/{print $2}')
        USED=$(free -m 2>/dev/null  | awk '/^Swap/{print $3}')
        FREE=$(free -m 2>/dev/null  | awk '/^Swap/{print $4}')
        echo -e "  总计：${BOLD}${TOTAL}MB${NC}  已用：${BOLD}${USED}MB${NC}  空闲：${BOLD}${FREE}MB${NC}"
    else
        echo -e "  ${YELLOW}当前未设置 Swap${NC}"
    fi
    echo ""
    # swappiness
    local SWAPPINESS
    SWAPPINESS=$(cat /proc/sys/vm/swappiness 2>/dev/null || echo "未知")
    echo -e "  swappiness：${BOLD}${SWAPPINESS}${NC}  ${DIM}（0=不用swap，60=默认，100=积极使用）${NC}"
}

# ── 创建 swap 文件 ────────────────────────────────────────
swap_create() {
    print_header "创建 Swap"

    # 检测是否在 OpenVZ/LXC（不支持 swap file）
    local IS_VIRT=false
    if grep -qa "lxc\|openvz" /proc/1/environ 2>/dev/null \
        || [ -f /proc/vz/veinfo ] \
        || grep -qa "container=lxc" /proc/1/environ 2>/dev/null; then
        IS_VIRT=true
    fi

    # 内存信息
    local MEM_MB; MEM_MB=$(free -m | awk '/^Mem/{print $2}')
    local DISK_FREE; DISK_FREE=$(df -m / | awk 'NR==2{print $4}')

    echo -e "  物理内存：${BOLD}${MEM_MB}MB${NC}  磁盘可用：${BOLD}${DISK_FREE}MB${NC}"
    echo ""

    if [ "$IS_VIRT" = true ]; then
        warn "检测到 LXC/OpenVZ 容器，可能不支持 swap file"
        warn "如果创建失败请联系 VPS 服务商开启 swap 权限"
        echo ""
    fi

    # 推荐大小
    local REC_SIZE
    if   [ "$MEM_MB" -le 512  ]; then REC_SIZE=1024
    elif [ "$MEM_MB" -le 1024 ]; then REC_SIZE=2048
    elif [ "$MEM_MB" -le 2048 ]; then REC_SIZE=2048
    elif [ "$MEM_MB" -le 4096 ]; then REC_SIZE=4096
    else                              REC_SIZE=4096
    fi

    echo -e "  推荐大小：${GREEN}${REC_SIZE}MB${NC}（基于当前内存 ${MEM_MB}MB）"
    echo ""
    menu_div
    menu_pair "1" "512 MB" "2" "1 GB"
    menu_pair "3" "2 GB · 推荐" "4" "4 GB"
    menu_item "5" "自定义大小"
    menu_pair "0" "返回上级" "00" "退出脚本" "$RED" "$RED"
    menu_div
    echo ""
    read -rp "$(ui_prompt '选择大小 [0-5]: ')" CH

    local SIZE_MB
    case "$CH" in
        1) SIZE_MB=512 ;;
        2) SIZE_MB=1024 ;;
        3) SIZE_MB=2048 ;;
        4) SIZE_MB=4096 ;;
        5)
            read -rp "  请输入大小（MB，如 512）: " SIZE_MB
            if ! echo "$SIZE_MB" | grep -qE '^[0-9]+$' || [ "$SIZE_MB" -lt 64 ]; then
                error "无效大小（最小 64MB）"; return
            fi
            ;;
        0) return ;;
        00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
        *) warn "无效选项"; return ;;
    esac

    # 检查磁盘空间
    if [ "$SIZE_MB" -gt "$DISK_FREE" ]; then
        error "磁盘空间不足（需要 ${SIZE_MB}MB，可用 ${DISK_FREE}MB）"
        return
    fi

    local SWAP_FILE NEW_SWAP OLD_SWAP
    SWAP_FILE="${SWAP_FILE:-/swapfile}"
    NEW_SWAP="${SWAP_FILE}.vps-tools.$$"
    OLD_SWAP="${SWAP_FILE}.vps-tools.bak.$$"

    echo ""
    info "正在创建 ${SIZE_MB}MB swap 文件..."

    # 用 fallocate 或 dd 创建文件
    if command -v fallocate &>/dev/null; then
        fallocate -l "${SIZE_MB}M" "$NEW_SWAP" 2>/dev/null || \
            dd if=/dev/zero of="$NEW_SWAP" bs=1M count="$SIZE_MB" status=none
    else
        dd if=/dev/zero of="$NEW_SWAP" bs=1M count="$SIZE_MB" status=progress
    fi

    if [ ! -f "$NEW_SWAP" ]; then
        error "Swap 文件创建失败"; return
    fi

    chmod 600 "$NEW_SWAP" || { rm -f "$NEW_SWAP"; return 1; }
    mkswap "$NEW_SWAP" &>/dev/null || { rm -f "$NEW_SWAP"; error "Swap 格式化失败"; return 1; }

    if swapon --show --noheadings 2>/dev/null | awk '{print $1}' | grep -qxF "$SWAP_FILE"; then
        warn "已存在 ${SWAP_FILE}，正在安全替换..."
        swapoff "$SWAP_FILE" 2>/dev/null || { rm -f "$NEW_SWAP"; error "旧 Swap 无法关闭，已取消替换"; return 1; }
    fi
    if [ -f "$SWAP_FILE" ]; then
        mv "$SWAP_FILE" "$OLD_SWAP" || { rm -f "$NEW_SWAP"; error "旧 Swap 文件备份失败"; return 1; }
    fi
    if ! mv "$NEW_SWAP" "$SWAP_FILE" || ! swapon "$SWAP_FILE" 2>/dev/null; then
        rm -f "$SWAP_FILE" "$NEW_SWAP"
        if [ -f "$OLD_SWAP" ]; then
            mv "$OLD_SWAP" "$SWAP_FILE"
            swapon "$SWAP_FILE" 2>/dev/null || true
        fi
        error "Swap 启用失败，已恢复旧文件"
        return 1
    fi
    rm -f "$OLD_SWAP"

    info "Swap 已启用 ✓"

    # 写入 /etc/fstab 持久化
    if ! awk -v target="$SWAP_FILE" '$1 == target {found=1} END {exit !found}' /etc/fstab 2>/dev/null; then
        echo "${SWAP_FILE} none swap sw 0 0" >> /etc/fstab || { error "无法写入 /etc/fstab，Swap 仅当前启动有效"; return 1; }
        info "已写入 /etc/fstab，重启后自动生效 ✓"
    fi

    echo ""
    swap_show_status
}

# ── 删除 swap ─────────────────────────────────────────────
swap_delete() {
    print_header "删除 Swap"

    local SWAPS
    SWAPS=$(swapon --show --noheadings 2>/dev/null | awk '{print $1}')

    if [ -z "$SWAPS" ]; then
        warn "当前没有启用的 Swap"
        return
    fi

    echo -e "  当前 Swap："
    local i=1
    local SWAP_LIST=()
    while IFS= read -r sw; do
        local SIZE; SIZE=$(swapon --show --bytes --noheadings 2>/dev/null | grep "^$sw" | awk '{printf "%.0fMB", $3/1048576}')
        echo -e "  ${GREEN}[$i]${NC} ${BOLD}${sw}${NC}  ${SIZE}"
        SWAP_LIST+=("$sw")
        i=$((i+1))
    done <<< "$SWAPS"

    echo ""
    menu_div
    echo -e "  ${DIM}输入编号删除，直接回车取消${NC}"
    read -rp "  请输入编号: " NUM
    [ -z "$NUM" ] && { warn "已取消"; return; }

    if ! echo "$NUM" | grep -qE '^[0-9]+$' || [ "$NUM" -lt 1 ] || [ "$NUM" -gt ${#SWAP_LIST[@]} ]; then
        error "无效编号"; return
    fi

    local TARGET="${SWAP_LIST[$((NUM-1))]}"
    echo ""
    warn "即将删除 Swap：${BOLD}${TARGET}${NC}"
    read -rp "  确认删除？(Y/n，默认Y): " CONFIRM
    [ -z "$CONFIRM" ] && CONFIRM="y"
    if ! echo "$CONFIRM" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    if ! swapoff "$TARGET" 2>/dev/null; then
        error "Swap 无法关闭，未修改 fstab，也未删除文件"
        return 1
    fi
    info "Swap 已关闭 ✓"

    # 从 fstab 移除
    if awk -v target="$TARGET" '$1 == target {found=1} END {exit !found}' /etc/fstab 2>/dev/null; then
        awk -v target="$TARGET" '$1 != target {print}' /etc/fstab > /etc/fstab.tmp \
            && mv /etc/fstab.tmp /etc/fstab || { error "更新 /etc/fstab 失败"; swapon "$TARGET" 2>/dev/null || true; return 1; }
        info "已从 /etc/fstab 移除 ✓"
    fi

    # 如果是文件则删除
    if [ -f "$TARGET" ]; then
        rm -f "$TARGET" && info "Swap 文件已删除 ✓"
    fi
}

# ── 修改 swappiness ───────────────────────────────────────
swap_swappiness_runtime_write() {
    local PROC_FILE="$1" VALUE="$2"
    printf '%s\n' "$VALUE" > "$PROC_FILE" 2>/dev/null
}

swap_swappiness_restore_state() {
    local PROC_FILE="$1" OLD_RUNTIME="$2" SYSCTL_FILE="$3" BACKUP="$4" EXISTED="$5"
    local RESTORE_TMP="" RESTORE_RC=0
    if [ "$EXISTED" = yes ]; then
        if [ -z "$BACKUP" ] || [ ! -f "$BACKUP" ]; then
            RESTORE_RC=1
        else
            RESTORE_TMP=$(mktemp "${SYSCTL_FILE}.vps-tools-restore.XXXXXX") || RESTORE_RC=1
            if [ "$RESTORE_RC" -eq 0 ]; then
                if ! cp -p -- "$BACKUP" "$RESTORE_TMP" \
                    || ! mv -f -- "$RESTORE_TMP" "$SYSCTL_FILE"; then
                    RESTORE_RC=1
                    rm -f -- "$RESTORE_TMP" 2>/dev/null || true
                fi
            fi
        fi
    else
        rm -f -- "$SYSCTL_FILE" 2>/dev/null || RESTORE_RC=1
    fi
    if ! [[ "$OLD_RUNTIME" =~ ^[0-9]+$ ]] \
        || ! swap_swappiness_runtime_write "$PROC_FILE" "$OLD_RUNTIME"; then
        RESTORE_RC=1
    fi
    return "$RESTORE_RC"
}

swap_swappiness_handle_failure() {
    local REASON="$1" PROC_FILE="$2" OLD_RUNTIME="$3"
    local SYSCTL_FILE="$4" BACKUP="$5" EXISTED="$6"
    if swap_swappiness_restore_state "$PROC_FILE" "$OLD_RUNTIME" \
        "$SYSCTL_FILE" "$BACKUP" "$EXISTED"; then
        rm -f -- "$BACKUP" 2>/dev/null || true
        error "$REASON，已恢复原设置"
        return 1
    fi
    error "$REASON，且自动回滚不完整"
    if [ -n "$BACKUP" ] && [ -f "$BACKUP" ]; then
        warn "原配置备份已保留，请人工恢复：$BACKUP"
    else
        warn "原配置备份不可用，请立即人工核对：$SYSCTL_FILE"
    fi
    warn "请同时核对当前运行值：$PROC_FILE"
    return 2
}

swap_apply_swappiness() {
    local VAL="$1"
    local PROC_FILE="${SWAPPINESS_PROC_FILE:-/proc/sys/vm/swappiness}"
    local SYSCTL_FILE="${SWAPPINESS_SYSCTL_FILE:-/etc/sysctl.conf}"
    local SYSCTL_DIR CANDIDATE BACKUP="" EXISTED=no OLD_RUNTIME ACTUAL CONFIG_INPUT=/dev/null
    local FAILURE_RC

    [[ "$VAL" =~ ^[0-9]+$ ]] && [ "$VAL" -le 100 ] || {
        error "无效值（0-100）"
        return 1
    }
    VAL=$((10#$VAL))
    [ -f "$PROC_FILE" ] && [ ! -L "$PROC_FILE" ] || {
        error "swappiness 运行参数不可用：$PROC_FILE"
        return 1
    }
    if [ -e "$SYSCTL_FILE" ] || [ -L "$SYSCTL_FILE" ]; then
        [ -f "$SYSCTL_FILE" ] && [ ! -L "$SYSCTL_FILE" ] || {
            error "sysctl 配置不是安全的普通文件：$SYSCTL_FILE"
            return 1
        }
        EXISTED=yes
    fi
    SYSCTL_DIR=$(dirname "$SYSCTL_FILE")
    [ -d "$SYSCTL_DIR" ] || {
        error "sysctl 配置目录不存在：$SYSCTL_DIR"
        return 1
    }
    OLD_RUNTIME=$(cat "$PROC_FILE" 2>/dev/null)
    [[ "$OLD_RUNTIME" =~ ^[0-9]+$ ]] || {
        error "无法读取当前 swappiness"
        return 1
    }

    CANDIDATE=$(mktemp "${SYSCTL_FILE}.vps-tools.XXXXXX") || {
        error "无法创建 sysctl 候选文件"
        return 1
    }
    if [ "$EXISTED" = yes ]; then
        CONFIG_INPUT="$SYSCTL_FILE"
        BACKUP=$(mktemp "${SYSCTL_FILE}.vps-tools-backup.XXXXXX") || {
            rm -f "$CANDIDATE"
            error "无法创建 sysctl 备份"
            return 1
        }
        if ! cp -p -- "$SYSCTL_FILE" "$BACKUP" \
            || ! cp -p -- "$SYSCTL_FILE" "$CANDIDATE"; then
            rm -f "$CANDIDATE" "$BACKUP"
            error "无法备份 sysctl 配置"
            return 1
        fi
    else
        chmod 644 "$CANDIDATE" 2>/dev/null || true
    fi

    if ! awk -v value="$VAL" '
        /^[[:space:]]*vm[.]swappiness[[:space:]]*=/ {
            if (!written) print "vm.swappiness = " value
            written=1
            next
        }
        { print }
        END {
            if (!written) print "vm.swappiness = " value
        }
    ' "$CONFIG_INPUT" > "$CANDIDATE"; then
        rm -f "$CANDIDATE" "$BACKUP"
        error "无法生成 sysctl 候选配置"
        return 1
    fi

    if ! swap_swappiness_runtime_write "$PROC_FILE" "$VAL"; then
        rm -f -- "$CANDIDATE"
        FAILURE_RC=1
        swap_swappiness_handle_failure "无法修改当前 swappiness" \
            "$PROC_FILE" "$OLD_RUNTIME" "$SYSCTL_FILE" "$BACKUP" "$EXISTED" \
            || FAILURE_RC=$?
        return "$FAILURE_RC"
    fi
    if ! mv -f -- "$CANDIDATE" "$SYSCTL_FILE"; then
        rm -f -- "$CANDIDATE" 2>/dev/null || true
        FAILURE_RC=1
        swap_swappiness_handle_failure "无法写入 sysctl 配置" \
            "$PROC_FILE" "$OLD_RUNTIME" "$SYSCTL_FILE" "$BACKUP" "$EXISTED" \
            || FAILURE_RC=$?
        return "$FAILURE_RC"
    fi
    ACTUAL=$(cat "$PROC_FILE" 2>/dev/null)
    ACTUAL=${ACTUAL//[[:space:]]/}
    if [ "$ACTUAL" != "$VAL" ]; then
        FAILURE_RC=1
        swap_swappiness_handle_failure \
            "swappiness 写后验证失败（期望 $VAL，实际 ${ACTUAL:-未知}）" \
            "$PROC_FILE" "$OLD_RUNTIME" "$SYSCTL_FILE" "$BACKUP" "$EXISTED" \
            || FAILURE_RC=$?
        return "$FAILURE_RC"
    fi
    if [ -n "$BACKUP" ] && ! rm -f -- "$BACKUP"; then
        warn "swappiness 已生效，但临时备份清理失败：$BACKUP"
    fi
}

swap_set_swappiness() {
    print_header "设置 Swappiness"
    local PROC_FILE="${SWAPPINESS_PROC_FILE:-/proc/sys/vm/swappiness}"
    local CUR; CUR=$(cat "$PROC_FILE" 2>/dev/null || echo 60)

    echo -e "  当前 swappiness：${BOLD}${CUR}${NC}"
    echo ""
    echo -e "  ${DIM}推荐值：${NC}"
    menu_item "1" "10 · 服务器推荐"
    menu_item "2" "30 · 折中"
    menu_item "3" "60 · 系统默认"
    menu_item "4" "自定义 0-100"
    menu_pair "0" "返回上级" "00" "退出脚本" "$RED" "$RED"
    echo ""
    read -rp "$(ui_prompt '选择 Swappiness [0-4]: ')" CH

    local VAL
    case "$CH" in
        1) VAL=10 ;;
        2) VAL=30 ;;
        3) VAL=60 ;;
        4)
            read -rp "  请输入值（0-100）: " VAL
            if ! echo "$VAL" | grep -qE '^[0-9]+$' || [ "$VAL" -gt 100 ]; then
                error "无效值（0-100）"; return
            fi
            ;;
        0) return ;;
        00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
        *) warn "无效选项"; return ;;
    esac

    local APPLY_RC=0
    swap_apply_swappiness "$VAL" || APPLY_RC=$?
    [ "$APPLY_RC" -eq 0 ] || return "$APPLY_RC"
    info "swappiness 已设置为 ${VAL}，重启后持续生效 ✓"
}

# ── Swap 主菜单 ───────────────────────────────────────────
swap_menu() {
    while true; do
        print_header "Swap 管理"
        swap_show_status
        menu_div
        menu_pair "1" "创建 / 更换 Swap" "2" "删除 Swap"
        menu_item "3" "设置 Swappiness"
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-3]: ')" CH

        case "$CH" in
            1) swap_create ;;
            2) swap_delete ;;
            3) swap_set_swappiness ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac

        [ "${CH}" != "0" ] && ui_pause
    done
}
# ══════════════════════════════════════════════════════════
#  STUN / UDP / NAT 检测
# ══════════════════════════════════════════════════════════

stun_ports_normalize() {
    local RAW="${1//,/ }" TOKEN OUT="" SEEN="," COUNT=0
    RAW="${RAW//;/ }"
    for TOKEN in $RAW; do
        case "$TOKEN" in ''|*[!0-9]*) return 1 ;; esac
        [ "$TOKEN" -ge 1 ] && [ "$TOKEN" -le 65535 ] || return 1
        case "$SEEN" in
            *",${TOKEN},"*) continue ;;
        esac
        COUNT=$((COUNT + 1))
        [ "$COUNT" -le 12 ] || return 1
        SEEN="${SEEN}${TOKEN},"
        if [ -n "$OUT" ]; then OUT="${OUT},${TOKEN}"; else OUT="$TOKEN"; fi
    done
    [ -n "$OUT" ] || return 1
    printf '%s\n' "$OUT"
}

stun_host_valid() {
    local HOST="$1"
    [ -n "$HOST" ] && [ "${#HOST}" -le 253 ] || return 1
    [[ "$HOST" =~ ^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$ ]] || return 1
    [[ "$HOST" != *..* ]]
}

stun_nat_type_label() {
    case "$1" in
        open_internet)       echo "公网直连（无 NAT）" ;;
        public_udp_firewall) echo "公网直连 + UDP 过滤" ;;
        full_cone)           echo "Full Cone（全锥型）" ;;
        restricted_cone)     echo "Restricted Cone（地址限制锥型）" ;;
        port_restricted)     echo "Port-Restricted Cone（端口限制锥型）" ;;
        symmetric)           echo "Symmetric NAT（对称型倾向）" ;;
        nat_unknown)         echo "检测到 NAT（细分未知）" ;;
        udp_unavailable)     echo "UDP / STUN 无有效响应" ;;
        *)                   echo "未知" ;;
    esac
}

stun_mapping_label() {
    case "$1" in
        eim)                echo "Endpoint-Independent" ;;
        adm)                echo "Address-Dependent" ;;
        apdm)               echo "Address-and-Port-Dependent" ;;
        endpoint_dependent) echo "Endpoint-Dependent" ;;
        *)                  echo "未知（证据不足）" ;;
    esac
}

stun_filtering_label() {
    case "$1" in
        eif)  echo "Endpoint-Independent" ;;
        adf)  echo "Address-Dependent" ;;
        apdf) echo "Address-and-Port-Dependent" ;;
        *)    echo "未知（服务器不支持或响应不足）" ;;
    esac
}

stun_confidence_label() {
    case "$1" in high) echo "高" ;; medium) echo "中" ;; *) echo "低" ;; esac
}

stun_udp_explanation() {
    local OK_COUNT="$1" TOTAL_COUNT="$2"
    if [ "$OK_COUNT" -eq 0 ]; then
        echo "无节点响应，请检查 UDP 出站、防火墙或上游网络"
    elif [ "$OK_COUNT" -eq "$TOTAL_COUNT" ]; then
        echo "全部节点响应，UDP 出站和返回流量正常"
    else
        echo "${OK_COUNT}/${TOTAL_COUNT} 节点响应，UDP 可用；失败多为节点或路由差异"
    fi
}

stun_nat_explanation() {
    case "$1" in
        open_internet)       echo "本机直接使用公网 IPv4，没有上游 NAT" ;;
        public_udp_firewall) echo "没有 NAT，但 UDP 返回流量受到防火墙限制" ;;
        full_cone)           echo "固定公网映射，外部来源均可回包，P2P 条件较好" ;;
        restricted_cone)     echo "固定映射，仅已联系过的目标 IP 可以回包" ;;
        port_restricted)     echo "固定映射，仅已联系过的目标 IP:端口可以回包" ;;
        symmetric)           echo "映射随目标改变，UDP 打洞和 P2P 直连较困难" ;;
        nat_unknown)         echo "确认存在 NAT，但证据不足，无法继续细分" ;;
        udp_unavailable)     echo "没有 STUN 响应，暂时无法判定 NAT" ;;
        *)                   echo "当前证据无法判断 NAT 类型" ;;
    esac
}

stun_mapping_explanation() {
    case "$1" in
        eim)                echo "访问不同目标时保持同一公网 IP:端口" ;;
        adm)                echo "目标 IP 改变时，公网映射会改变" ;;
        apdm)               echo "目标 IP 或端口改变时，公网映射会改变" ;;
        endpoint_dependent) echo "公网映射随目标变化，依赖类型尚无法细分" ;;
        *)                  echo "响应不足，无法确定公网端口映射规律" ;;
    esac
}

stun_filtering_explanation() {
    case "$1" in
        eif)  echo "建立映射后，任意外部来源均可回包" ;;
        adf)  echo "仅已主动访问的目标 IP 可以回包" ;;
        apdf) echo "仅已主动访问的目标 IP:端口可以回包" ;;
        *)    echo "服务器缺少辅助能力，暂时无法确定回包限制" ;;
    esac
}

stun_confidence_explanation() {
    case "$1" in
        high)   echo "映射和过滤证据完整，判定可靠性较高" ;;
        medium) echo "已获得公网映射，但部分辅助证据不足" ;;
        *)      echo "有效响应或辅助证据不足，结果仅供参考" ;;
    esac
}

stun_recommendation() {
    case "$1" in
        open_internet)       echo "入站仍需确认本机防火墙和服务监听" ;;
        public_udp_firewall) echo "检查本机或上游防火墙的 UDP 入站规则" ;;
        full_cone|restricted_cone|port_restricted)
                             echo "需要公网入站时，优先配置固定端口转发" ;;
        symmetric|nat_unknown)
                             echo "入站服务需端口转发、DMZ、1:1 NAT 或公网 IP" ;;
        *)                   echo "先确认服务商是否允许 UDP，再检查本机防火墙" ;;
    esac
}

stun_ensure_python() {
    command -v python3 >/dev/null 2>&1 && return 0
    info "正在安装 Python 3..."
    if command -v opkg >/dev/null 2>&1; then
        opkg update >/dev/null 2>&1 && opkg install python3 >/dev/null 2>&1
    else
        pkg_install python3 >/dev/null 2>&1
    fi
    command -v python3 >/dev/null 2>&1 || {
        error "STUN 检测需要 Python 3"
        return 1
    }
}

stun_probe_engine() {
    local MODE="$1" HOST="${2:--}" PORTS="${3:--}"
    python3 - "$MODE" "$HOST" "$PORTS" <<'PY'
import ipaddress
import secrets
import socket
import struct
import sys
import time

COOKIE = 0x2112A442
COOKIE_BYTES = struct.pack("!I", COOKIE)


def emit(*values):
    clean = []
    for value in values:
        text = str(value).replace("\t", " ").replace("\r", " ").replace("\n", " ")
        clean.append(text if text else "-")
    print("\t".join(clean))


def decode_address(value, txid, xor_address=False):
    if len(value) < 4:
        raise ValueError("short address")
    family = value[1]
    port = struct.unpack("!H", value[2:4])[0]
    if xor_address:
        port ^= COOKIE >> 16
    if family == 0x01:
        size = 4
        af = socket.AF_INET
    elif family == 0x02:
        size = 16
        af = socket.AF_INET6
    else:
        raise ValueError("unsupported address family")
    if len(value) < 4 + size:
        raise ValueError("short address value")
    packed = value[4:4 + size]
    if xor_address:
        key = COOKIE_BYTES + txid
        packed = bytes(a ^ b for a, b in zip(packed, key[:size]))
    return socket.inet_ntop(af, packed), port


def parse_message(data, expected_txid):
    if len(data) < 20:
        raise ValueError("short STUN header")
    msg_type, msg_len, cookie, txid = struct.unpack("!HHI12s", data[:20])
    if cookie != COOKIE or txid != expected_txid or msg_len > len(data) - 20:
        raise ValueError("invalid STUN response")
    result = {"type": msg_type, "txid": txid}
    offset = 20
    end = 20 + msg_len
    while offset + 4 <= end:
        attr_type, attr_len = struct.unpack("!HH", data[offset:offset + 4])
        value_start = offset + 4
        value_end = value_start + attr_len
        if value_end > end:
            raise ValueError("invalid STUN attribute length")
        value = data[value_start:value_end]
        try:
            if attr_type == 0x0020:
                result["xor_mapped"] = decode_address(value, txid, True)
            elif attr_type == 0x0001:
                result["mapped"] = decode_address(value, txid, False)
            elif attr_type == 0x0005:
                result["changed"] = decode_address(value, txid, False)
            elif attr_type == 0x802B:
                result["response_origin"] = decode_address(value, txid, False)
            elif attr_type == 0x802C:
                result["other"] = decode_address(value, txid, False)
            elif attr_type == 0x0009 and len(value) >= 4:
                result["error"] = (value[2] & 0x07) * 100 + value[3]
        except (OSError, ValueError):
            pass
        offset = value_start + ((attr_len + 3) // 4) * 4
    result["mapped_address"] = result.get("xor_mapped") or result.get("mapped")
    return result


def binding_request(sock, address, change_flags=0, timeout=1.0, retries=2):
    txid = secrets.token_bytes(12)
    attrs = struct.pack("!HHI", 0x0003, 4, change_flags) if change_flags else b""
    packet = struct.pack("!HHI12s", 0x0001, len(attrs), COOKIE, txid) + attrs
    started = time.monotonic()
    last_error = "timeout"
    for _ in range(retries):
        try:
            sock.sendto(packet, address)
        except OSError as exc:
            return None, exc.__class__.__name__, int((time.monotonic() - started) * 1000)
        deadline = time.monotonic() + timeout
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            sock.settimeout(remaining)
            try:
                data, source = sock.recvfrom(4096)
            except socket.timeout:
                break
            except OSError as exc:
                last_error = exc.__class__.__name__
                break
            try:
                response = parse_message(data, txid)
            except ValueError:
                continue
            response["source"] = (source[0], source[1])
            elapsed = int((time.monotonic() - started) * 1000)
            if response.get("type") == 0x0101 and response.get("mapped_address"):
                return response, "ok", elapsed
            if response.get("type") == 0x0111:
                return response, "stun_error", elapsed
    return None, last_error, int((time.monotonic() - started) * 1000)


def route_source_ip(address):
    probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        probe.connect(address)
        return probe.getsockname()[0]
    except OSError:
        return "-"
    finally:
        probe.close()


def safe_other_address(address):
    if not address:
        return False
    try:
        ip = ipaddress.ip_address(address[0])
        return ip.version == 4 and ip.is_global and 1 <= int(address[1]) <= 65535
    except (ValueError, TypeError):
        return False


def classify_nat(success_count, has_nat, mapping, filtering):
    if success_count == 0:
        return "udp_unavailable"
    if has_nat is False:
        if filtering in ("adf", "apdf"):
            return "public_udp_firewall"
        return "open_internet"
    if mapping in ("adm", "apdm", "endpoint_dependent"):
        return "symmetric"
    if mapping == "eim":
        if filtering == "eif":
            return "full_cone"
        if filtering == "adf":
            return "restricted_cone"
        if filtering == "apdf":
            return "port_restricted"
    return "nat_unknown"


def self_test():
    txid = bytes(range(12))
    expected_ip = "203.0.113.7"
    expected_port = 54321
    raw_ip = socket.inet_pton(socket.AF_INET, expected_ip)
    encoded_ip = bytes(a ^ b for a, b in zip(raw_ip, COOKIE_BYTES))
    encoded_port = expected_port ^ (COOKIE >> 16)
    value = b"\x00\x01" + struct.pack("!H", encoded_port) + encoded_ip
    attribute = struct.pack("!HH", 0x0020, len(value)) + value
    packet = struct.pack("!HHI12s", 0x0101, len(attribute), COOKIE, txid) + attribute
    parsed = parse_message(packet, txid)
    assert parsed["mapped_address"] == (expected_ip, expected_port)
    try:
        parse_message(packet, b"wrong-tx-id!")
        raise AssertionError("transaction ID mismatch was accepted")
    except ValueError:
        pass
    assert classify_nat(2, True, "eim", "eif") == "full_cone"
    assert classify_nat(2, True, "eim", "adf") == "restricted_cone"
    assert classify_nat(2, True, "eim", "apdf") == "port_restricted"
    assert classify_nat(2, True, "apdm", "unknown") == "symmetric"
    assert classify_nat(2, False, "eim", "apdf") == "public_udp_firewall"
    assert classify_nat(0, None, "unknown", "unknown") == "udp_unavailable"
    emit("SELFTEST", "ok")


def endpoint_list(mode, host, ports):
    if mode == "quick":
        return [
            ("stun.nextcloud.com", 443),
            ("stun.nextcloud.com", 3478),
            ("stun.cloudflare.com", 3478),
            ("stun.l.google.com", 19302),
            ("stun.miwifi.com", 3478),
        ]
    return [(host, int(port)) for port in ports.split(",")]


def main(mode, host, ports):
    if mode == "selftest":
        self_test()
        return
    endpoints = endpoint_list(mode, host, ports)
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.bind(("0.0.0.0", 0))
    local_port = sock.getsockname()[1]
    results = []
    for endpoint_host, endpoint_port in endpoints:
        record = {"host": endpoint_host, "port": endpoint_port, "status": "dns_error"}
        try:
            answers = socket.getaddrinfo(endpoint_host, endpoint_port, socket.AF_INET, socket.SOCK_DGRAM)
            resolved_ip = answers[0][4][0]
            address = (resolved_ip, endpoint_port)
            record.update({"resolved": resolved_ip, "address": address})
            response, status, elapsed = binding_request(sock, address)
            record.update({"response": response, "status": status, "elapsed": elapsed})
            if response and response.get("mapped_address"):
                record["mapped"] = response["mapped_address"]
        except (OSError, ValueError) as exc:
            record["error"] = exc.__class__.__name__
        results.append(record)

    successful = [record for record in results if record.get("mapped")]
    local_ip = route_source_ip(successful[0]["address"]) if successful else "-"
    external = successful[0]["mapped"] if successful else None

    evidence = []
    for index, left in enumerate(successful):
        for right in successful[index + 1:]:
            if left["address"] != right["address"]:
                evidence.append((left["address"], left["mapped"], right["address"], right["mapped"]))

    for record in successful:
        other = record["response"].get("other") or record["response"].get("changed")
        if safe_other_address(other) and other != record["address"]:
            other_response, _, _ = binding_request(sock, other)
            if other_response and other_response.get("mapped_address"):
                evidence.append((record["address"], record["mapped"], other, other_response["mapped_address"]))

    same_ip_equal = same_ip_diff = cross_ip_equal = cross_ip_diff = False
    for first_address, first_mapping, second_address, second_mapping in evidence:
        same_mapping = first_mapping == second_mapping
        if first_address[0] == second_address[0] and first_address[1] != second_address[1]:
            same_ip_equal |= same_mapping
            same_ip_diff |= not same_mapping
        elif first_address[0] != second_address[0]:
            cross_ip_equal |= same_mapping
            cross_ip_diff |= not same_mapping
    if same_ip_diff:
        mapping = "apdm"
    elif cross_ip_diff:
        mapping = "adm" if same_ip_equal else "endpoint_dependent"
    elif same_ip_equal or cross_ip_equal:
        mapping = "eim"
    else:
        mapping = "unknown"

    filtering = "unknown"
    filtering_evidence = False
    for record in successful:
        response = record["response"]
        other = response.get("other") or response.get("changed")
        if not safe_other_address(other):
            continue
        origin = response.get("source")
        alternate_ip_available = bool(origin and other[0] != origin[0])
        changed, changed_status, _ = binding_request(sock, record["address"], 0x06)
        if changed and origin and changed.get("source") != origin:
            changed_source = changed["source"]
            if changed_source[0] != origin[0]:
                filtering = "eif"
                filtering_evidence = True
                break
            # A port-only source change does not prove that the server honored CHANGE-IP.
            continue
        if changed and origin and changed.get("source") == origin:
            continue
        changed_port, port_status, _ = binding_request(sock, record["address"], 0x02)
        if alternate_ip_available and changed_port and origin and changed_port.get("source") != origin:
            port_source = changed_port["source"]
            filtering = "eif" if port_source[0] != origin[0] else "adf"
            filtering_evidence = True
            break
        if changed_port and origin and changed_port.get("source") == origin:
            continue
        if alternate_ip_available and changed_status == "timeout" and port_status == "timeout":
            filtering = "apdf"
            filtering_evidence = True
            break

    has_nat = None
    if external and local_ip != "-":
        has_nat = external[0] != local_ip
    nat_type = classify_nat(len(successful), has_nat, mapping, filtering)
    if nat_type in ("open_internet", "public_udp_firewall") and filtering_evidence:
        confidence = "high"
    elif mapping != "unknown" and filtering_evidence:
        confidence = "high"
    elif len(successful) >= 2 or has_nat is not None:
        confidence = "medium"
    else:
        confidence = "low"

    for record in results:
        mapped = record.get("mapped")
        mapped_text = f"{mapped[0]}:{mapped[1]}" if mapped else "-"
        emit(
            "PROBE", record["host"], record["port"], record.get("resolved", "-"),
            "ok" if mapped else record.get("status", "error"), mapped_text,
            record.get("elapsed", "-"), record.get("error", "-"),
        )
    for port in sorted({record["port"] for record in results}):
        port_records = [record for record in results if record["port"] == port]
        ok_count = sum(1 for record in port_records if record.get("mapped"))
        emit("PORT", port, ok_count, len(port_records))
    external_text = f"{external[0]}:{external[1]}" if external else "-"
    emit(
        "SUMMARY", local_ip, local_port, external_text, mapping, filtering, nat_type,
        confidence, len(successful), len(results),
    )
    sock.close()


try:
    main(sys.argv[1], sys.argv[2], sys.argv[3])
except Exception as exc:
    emit("FATAL", exc.__class__.__name__)
    raise SystemExit(1)
PY
}

stun_render_results() {
    local OUTPUT="$1" KIND A B C D E F G H I
    local LOCAL_IP="-" LOCAL_PORT="-" EXTERNAL="-" MAPPING="unknown" FILTERING="unknown"
    local NAT_TYPE="unknown" CONFIDENCE="low" OK_COUNT=0 TOTAL_COUNT=0

    echo -e "  ${BOLD}STUN 端点${NC}"
    while IFS=$'\t' read -r KIND A B C D E F G H I; do
        case "$KIND" in
            PROBE)
                if [ "$D" = "ok" ]; then
                    echo -e "  ${GREEN}✓${NC}  ${A}:${B}  ${BOLD}${E}${NC}  ${DIM}${F}ms${NC}"
                else
                    echo -e "  ${RED}×${NC}  ${A}:${B}  ${YELLOW}${D}${NC}"
                fi
                ;;
            PORT)
                printf '  UDP/%-5s  %s/%s 响应\n' "$A" "$B" "$C"
                ;;
            SUMMARY)
                LOCAL_IP="$A"; LOCAL_PORT="$B"; EXTERNAL="$C"; MAPPING="$D"; FILTERING="$E"
                NAT_TYPE="$F"; CONFIDENCE="$G"; OK_COUNT="$H"; TOTAL_COUNT="$I"
                ;;
            FATAL)
                error "STUN 协议引擎执行失败：${A}"
                return 1
                ;;
        esac
    done <<< "$OUTPUT"

    echo ""
    menu_div
    echo -e "  本地出口 : ${BOLD}${LOCAL_IP}:${LOCAL_PORT}${NC}"
    echo -e "  公网映射 : ${BOLD}${EXTERNAL}${NC}"
    echo -e "  有效响应 : ${BOLD}${OK_COUNT}/${TOTAL_COUNT}${NC}"
    echo -e "  IPv4 NAT : ${CYAN}${BOLD}$(stun_nat_type_label "$NAT_TYPE")${NC}"
    echo -e "  映射行为 : ${BOLD}$(stun_mapping_label "$MAPPING")${NC}"
    echo -e "  过滤行为 : ${BOLD}$(stun_filtering_label "$FILTERING")${NC}"
    echo -e "  判定置信 : ${BOLD}$(stun_confidence_label "$CONFIDENCE")${NC}"
    menu_div
    echo -e "  ${BOLD}结果解释${NC}"
    echo -e "  ${CYAN}UDP${NC}  : $(stun_udp_explanation "$OK_COUNT" "$TOTAL_COUNT")"
    echo -e "  ${CYAN}NAT${NC}  : $(stun_nat_explanation "$NAT_TYPE")"
    echo -e "  ${CYAN}映射${NC} : $(stun_mapping_explanation "$MAPPING")"
    echo -e "  ${CYAN}过滤${NC} : $(stun_filtering_explanation "$FILTERING")"
    echo -e "  ${CYAN}置信${NC} : $(stun_confidence_explanation "$CONFIDENCE")"
    echo -e "  ${CYAN}建议${NC} : $(stun_recommendation "$NAT_TYPE")"
    menu_div
}

stun_probe_execute() {
    local MODE="$1" HOST="${2:--}" PORTS="${3:--}" OUTPUT
    stun_ensure_python || return 1
    info "正在执行 STUN 与多端口 UDP 探测..."
    if ! OUTPUT=$(stun_probe_engine "$MODE" "$HOST" "$PORTS"); then
        error "STUN 检测执行失败"
        return 1
    fi
    stun_render_results "$OUTPUT" || return 1
    audit_action "STUN NAT 检测 ${MODE} ${HOST} ${PORTS}" SUCCESS
}

stun_nat_quick() {
    print_header "STUN / NAT 检测"
    stun_probe_execute quick
}

stun_nat_custom() {
    print_header "自定义 STUN 多端口"
    local HOST PORT_INPUT PORTS
    read -rp "  STUN 主机（默认 stun.nextcloud.com）: " HOST
    HOST=${HOST:-stun.nextcloud.com}
    stun_host_valid "$HOST" || { error "STUN 主机格式无效"; return 1; }
    read -rp "  UDP 端口（逗号分隔，默认 443,3478）: " PORT_INPUT
    PORT_INPUT=${PORT_INPUT:-443,3478}
    PORTS=$(stun_ports_normalize "$PORT_INPUT") || {
        error "端口格式无效，仅支持 1-65535，最多 12 个"
        return 1
    }
    echo ""
    stun_probe_execute custom "$HOST" "$PORTS"
}

stun_nat_menu() {
    while true; do
        print_header "STUN / NAT 检测"
        menu_item "1" "快速检测"
        menu_item "2" "自定义 STUN 多端口" "$CYAN"
        menu_item "0" "返回上级" "$RED"
        menu_div
        echo ""
        local CH
        read -rp "$(ui_prompt '选择操作 [0-2]: ')" CH
        case "$CH" in
            1) stun_nat_quick; ui_pause ;;
            2) stun_nat_custom; ui_pause ;;
            0) return ;;
            *) warn "无效选项"; sleep 1 ;;
        esac
    done
}
