monitor_time_normalize() {
    local IN="${1:-}" HH MM
    IN=${IN//[[:space:]]/}
    case "$IN" in
        [0-9][0-9]:[0-9][0-9])
            HH=${IN%:*}
            MM=${IN#*:}
            ;;
        [0-9][0-9][0-9][0-9])
            HH=${IN:0:2}
            MM=${IN:2:2}
            ;;
        *)
            return 1
            ;;
    esac
    echo "$HH" | grep -qE '^[0-9]+$' || return 1
    echo "$MM" | grep -qE '^[0-9]+$' || return 1
    [ "$HH" -lt 24 ] || return 1
    [ "$MM" -lt 60 ] || return 1
    printf '%02d:%02d\n' "$((10#$HH))" "$((10#$MM))"
}

monitor_date_normalize() {
    local IN="${1:-}" Y M D
    IN=${IN//[[:space:]]/}
    case "$IN" in
        [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9])
            Y=${IN%%-*}
            M=${IN#*-}; M=${M%-*}
            D=${IN##*-}
            ;;
        [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9])
            Y=${IN:0:4}
            M=${IN:4:2}
            D=${IN:6:2}
            ;;
        *)
            return 1
            ;;
    esac
    python3 - "$Y" "$M" "$D" <<'PY'
from datetime import date
import sys
y, m, d = map(int, sys.argv[1:])
print(date(y, m, d).isoformat())
PY
}

monitor_alert_host_label() {
