        echo "$MON_HOST_LABEL"
    else
        hostname 2>/dev/null || echo unknown
    fi
}

monitor_alert_html_escape() {
    local VALUE="${1:-}"
    VALUE=${VALUE//&/\&amp;}
    VALUE=${VALUE//</\&lt;}
    VALUE=${VALUE//>/\&gt;}
    printf '%s' "$VALUE"
}

monitor_alert_host_label_html() {
