# ── 后台版本检测 ────────────────────────────────────────
self_check_update() {
    local REMOTE_VER
    REMOTE_VER=$(curl -fsSL --max-time 5 "$SCRIPT_URL" 2>/dev/null \
        | grep -oE 'VPS 开荒脚本 V[0-9]+[.][0-9]+[.][0-9]+|VPS 开荒脚本 V[0-9]+[.][0-9]+' \
        | head -1 | grep -oE 'V[0-9]+[.][0-9]+([.][0-9]+)?')
    [ -z "$REMOTE_VER" ] && return
    local CUR_VER
    CUR_VER=$(grep -oE 'VPS 开荒脚本 V[0-9]+[.][0-9]+[.][0-9]+|VPS 开荒脚本 V[0-9]+[.][0-9]+' "$0" 2>/dev/null \
        | head -1 | grep -oE 'V[0-9]+[.][0-9]+([.][0-9]+)?')
    [ -z "$CUR_VER" ] && return
    if [ "$REMOTE_VER" = "$CUR_VER" ]; then
        rm -f "$UPDATE_NOTICE_FILE" 2>/dev/null
        return
    fi
    mkdir -p "$VPS_DATA_DIR" 2>/dev/null || return
    chmod 700 "$VPS_DATA_DIR" 2>/dev/null || true
    printf '%s\n' "$REMOTE_VER" > "$UPDATE_NOTICE_FILE" 2>/dev/null
}

